import React from "react"
import dayjs from "dayjs"
import {
    Bar,
    BarChart,
    CartesianGrid,
    ResponsiveContainer,
    Tooltip,
    XAxis,
    YAxis,
} from "recharts"
import { AsyncContent } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Chip, type ChipTone } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `AiQuotaHistoryPanel` — the "History" tab body inside `AiQuotaModal`: a 7-day
 * usage bar chart plus a scrollable, bordered list of recent AI charges.
 * `isLoading` swaps the whole `ChargesList` region for its shimmer mirror; an
 * empty `items` array renders the list's own empty state. The chart draws from
 * `chartPoints` regardless of either.
 */

/** What an AI charge was for — the block owns the display label per surface. */
export type AiQuotaHistorySurface = "grade" | "interview" | "chatbot"

/** {@link AiQuotaHistorySurface} → its display label. The block's own vocabulary (§14d.1). */
const PURPOSE_LABEL: Record<AiQuotaHistorySurface, string> = {
    grade: "Challenge grading",
    interview: "Interview grading",
    chatbot: "AI chat",
}

/** Fallback row title when a charge carries no specific model name. */
const AUTO_MODEL_LABEL = "Automatic model (free)"

/** Unit suffix on every credit-delta chip. */
const CREDITS_UNIT = "credit"

/** One day-bucket plotted on the usage chart. */
export interface AiQuotaHistoryChartPoint {
    /** X-axis label, already formatted (e.g. `"12/07"`). */
    day: string
    /** Credits consumed that day. */
    credits: number
}

/** One row of the recent-charges list. */
export interface AiQuotaHistoryChargeItem {
    /** Stable React key. */
    key: string
    /** Model name, when the charge names one specifically. Falls back to {@link AUTO_MODEL_LABEL}. */
    model?: string
    /** What the charge was for — drives the block-owned {@link PURPOSE_LABEL}. */
    surface: AiQuotaHistorySurface
    /** When the charge happened — the block formats this itself (`HH:mm DD/MM`). */
    occurredAt: string | number | Date
    /** Credit delta for this charge. Sign drives the trailing chip's tone (see judgement call 4). */
    credits: number
}

/** Props for {@link AiQuotaHistoryPanel}. */
export interface AiQuotaHistoryPanelProps {
    /** The 7 day-buckets for the chart. Defaults to an empty plot when omitted. */
    chartPoints?: Array<AiQuotaHistoryChartPoint>
    /** Recent charges, most recent first. `undefined` while the first load is still running. */
    items?: Array<AiQuotaHistoryChargeItem>
    /** `true` while the charges list's first load is running (drives ONLY the `ChargesList` leaf). */
    isLoading: boolean
    /** Where this sits inside its parent. Appearance is not passable — it is already a prop. */
    classNames?: Array<AllowedClassName>
}

/** How many placeholder rows the loading mirror shows — matches the source's 3-row skeleton. */
const SKELETON_ROW_COUNT = 3

/** Chip tone for a credit delta — see judgement call 4 in the file header: ported verbatim. */
const deltaTone = (credits: number): ChipTone => (credits > 0 ? "warning" : "success")

const toListItem = (item: AiQuotaHistoryChargeItem): SurfaceCardListItem => ({
    key: item.key,
    title: item.model ?? AUTO_MODEL_LABEL,
    subtitle: `${PURPOSE_LABEL[item.surface]} · ${dayjs(item.occurredAt).format("HH:mm DD/MM")}`,
    meta: () => <Chip tone={deltaTone(item.credits)} text={`${item.credits} ${CREDITS_UNIT}`} />,
})

/** Placeholder rows for the loading mirror — same row shape, shimmer chip in the meta slot. */
const skeletonItems = (): Array<SurfaceCardListItem> => Array.from({ length: SKELETON_ROW_COUNT }, (_, index) => ({
    key: `skeleton-${index}`,
    title: "Model",
    subtitle: "Purpose · Time",
    meta: () => <Chip isSkeleton />,
}))

/**
 * History tab body of `AiQuotaModal` — usage chart + recent-charges list.
 *
 * @param props - {@link AiQuotaHistoryPanelProps}
 */
export const AiQuotaHistoryPanel = ({
    chartPoints = [],
    items,
    isLoading,
    classNames,
}: AiQuotaHistoryPanelProps) => {
    const isEmpty = !isLoading && (items?.length ?? 0) === 0

    const chart = (
        <StackV gap={4} principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            items={[
                () => <Typography size="sm" weight="medium" text="Credits used per day (last 7 days)" />,
                () => (
                    <SurfaceCard
                        variant="nested"
                        padding={4}

                        body={() => (
                            <div className="h-44 w-full text-accent-soft-foreground">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={chartPoints} margin={{ top: 8, right: 8, bottom: 0, left: -16 }}>
                                        <CartesianGrid
                                            strokeDasharray="3 3"
                                            stroke="currentColor"
                                            className="text-divider"
                                            vertical={false}
                                        />
                                        <XAxis dataKey="day" tick={{ fontSize: 10 }} interval={0} tickLine={false} axisLine={false} />
                                        <YAxis allowDecimals={false} tick={{ fontSize: 10 }} tickLine={false} axisLine={false} width={28} />
                                        <Tooltip
                                            cursor={{ fill: "currentColor", opacity: 0.08 }}
                                            formatter={(value) => [`${value} ${CREDITS_UNIT}`, ""]}
                                        />
                                        <Bar dataKey="credits" fill="currentColor" radius={[4, 4, 0, 0]} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        )}
                    />
                ),
            ]} />
    )

    const chargesList = (
        <StackV gap={4} items={[
            () => <Typography size="sm" weight="medium" text="AI usage history" />,
            () => (
                <div className="max-h-64 overflow-y-auto">
                    <AsyncContent
                        isLoading={isLoading}
                        skeleton={() => <SurfaceCardList variant="nested" items={skeletonItems()} isSkeleton />}
                        isEmpty={isEmpty}
                        emptyContent={{
                            title: "No AI usage yet.",

                        }}
                        content={() => <SurfaceCardList variant="nested" items={(items ?? []).map((item) => toListItem(item))} />}

                    />
                </div>
            ),
        ]} />
    )

    return (
        <div>
            <StackV gap={6} classNames={classNames} items={[() => chart, () => chargesList]} />
        </div>
    )
}

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { Popover } from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { KeyValueList } from "@sb-components/composites/data/KeyValue/KeyValue"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"

/**
 * DESIGN — a single course/product price: the amount to pay (bold), the struck
 * list price, a `−X%` success chip, and a breakdown popover.
 *
 * ANATOMY IS PER-LEAF: each story below is its OWN leaf and wraps its render in
 * its OWN BlockAnatomy (Diagram + Tree) reflecting the parts THAT leaf composes —
 * there is no separate consolidated "Anatomy" story. The composition shifts with
 * the shape: no-discount shows only the amount; on-sale adds the struck price,
 * chip, popover, and saving line; `showSavingLine={false}` drops that last line.
 */

/** Currency a price is shown in. */
export type PriceCurrency = "VND" | "USD"

/**
 * How loud the price is on its surface — decides the amount's font size. INTERNAL,
 * and deliberately NOT named `role`: that word is a DOM/ARIA attribute, so a prop by
 * that name reads as an accessibility role to both a reader and to eslint-jsx-a11y
 * (which flagged `role="prominent"` as an invalid ARIA role three times).
 * not exposed as a prop (§14d.1): the caller picks a MEMBER (`PriceTagInline` /
 * `PriceTagProminent`), not a size.
 */
export type PriceEmphasis = "inline" | "prominent"

/** Breakdown rows for the breakdown popover (amounts in the SAME currency as the price). */
export interface PriceBreakdown {
    /** Active-phase price BEFORE loyalty (the middle step list -> phase -> charge). */
    phase: number
    /** Localised phase name (e.g. "Early-bird") shown on the phase row. */
    phaseLabel?: string
    /** Loyalty discount percent (0 = no loyalty row). */
    loyaltyPercent: number
    /** Localised loyalty note (e.g. "already owns 2 courses") appended to the loyalty row. */
    loyaltyNote?: string
}

/** Props for the {@link PriceTag} block. */
export interface PriceTagProps {
    /** The price the user actually pays. */
    discounted: number
    /** The pre-discount (list/MSRP) price; struck through when greater than discounted. */
    original?: number | null
    /** Currency to format in. Defaults to "VND". */
    currency?: PriceCurrency
    /**
 * `true` -> the price is in its RESTING state: the amount, the struck-through
 * original price, the `−X%` chip, and the saving line all turn to shimmer,
 * KEEPING the same line boxes so nothing jumps in layout (§8).
 *
 * The flag FLOWS DOWN into the atoms that render each part (`Typography`,
 * `Chip`), instead of building a second shimmer tree (§12c). The popover
 * is TURNED OFF while resting — there is no data to open yet, and a pressable
 * control while loading is a false promise.
 */
    isSkeleton?: boolean
    /**
 * Optional phase-tier + loyalty rows for the breakdown {@link Popover}. Whenever
 * there IS a saving the `−X%` chip is ALWAYS a button that opens the popover (at
 * minimum list price -> "you pay"); `breakdown` just adds the middle steps that
 * explain WHERE the drop came from. Click/tap (not hover) so it works on touch too.
 */
    breakdown?: PriceBreakdown
    /**
 * Show the concrete "save N₫" line under the price (the real VND saved, not just
 * the percent). Defaults to `true`; set `false` where space is tight (dense cards).
 */
    showSavingLine?: boolean
    /** Where the root sits inside its parent. */
    classNames?: Array<AllowedClassName>
}

/**
 * Role -> amount font size.
 */
const AMOUNT_TYPE: Record<PriceEmphasis, "base" | "h4"> = {
    inline: "base",
    prominent: "h4",
}

/** Role -> struck-through original-price line size, placed next to {@link AMOUNT_TYPE} so the two scales don't drift apart. */
const ORIGINAL_TYPE: Record<PriceEmphasis, "xs" | "sm"> = {
    inline: "xs",
    prominent: "sm",
}

/** Format an amount in the given currency. */
const formatPrice = (amount: number, currency: PriceCurrency): string =>
    currency === "USD"
        ? amount.toLocaleString("en-US", { style: "currency", currency: "USD" })
        : `${amount.toLocaleString("vi-VN")}₫`

/** Whole-percent saving between a "before" and an "after" amount (0 when none). */
const savingPercent = (before: number, after: number): number =>
    before > after ? Math.round((1 - after / before) * 100) : 0

/**
 * The single source of truth for rendering a course/product price: the discounted
 * amount (bold), the list price struck through (only when there IS a saving), and a
 * `−X%` success chip whose percent is the REAL list -> charge gap (phase tier +
 * loyalty). Whenever there is a saving the chip is a clickable button opening a
 * {@link Popover} (at minimum list price -> you pay; `breakdown` adds the phase +
 * loyalty steps). Works in VND or USD.
 *
 * @param props - {@link PriceTagProps}
 */
export const PriceTagBase = ({
    discounted,
    original,
    currency = "VND",
    emphasis,
    isSkeleton = false,
    breakdown,
    showSavingLine = true,
    classNames,
}: PriceTagProps & { emphasis: PriceEmphasis }) => {
    const hasSaving = original != null && original > discounted
    const savePercent = hasSaving ? savingPercent(original, discounted) : 0

    // the −X% saving chip — composed from the `Chip` atom (tone success ->
    // soft-success chip, matching src's raw `<Chip variant="soft" color="success">`).
    // The pressable/focusable button role lives on the canonical `Popover.Trigger`
    // wrapper (react-aria: role=button, aria-expanded/controls, tabindex), so there is
    // exactly ONE interactive element. No caret; the whole chip is the affordance.
    const chip =
        savePercent > 0 ? (
            <Chip
                tone="success"
                text={`−${savePercent}%`}
            />
        ) : null

    // phase saving = list -> phase ; loyalty saving = phase -> charge
    const phaseSave = original != null ? savingPercent(original, breakdown?.phase ?? discounted) : 0
    // Popover content — shown for EVERY saving (so the chip is always clickable), at
    // minimum list price -> you pay. The phase-tier & loyalty rows only appear when a
    // full `breakdown` is supplied.
    const breakdownContent = hasSaving ? (
        // Those four rows are all ONE shape: label left <-> value right, repeated =>
        // exactly `KeyValueList` (a repeated list => `items` is DATA). The "you
        // pay" row is the TOTAL row => `emphasis`, not a hand-drawn rule: the frame
        // already knows how to emphasise a total row, and that emphasis looks the same
        // across every price table in the system.
        //
        // NOTE: The frame does NOT format for you: every money string coming in here
        // has already gone through `formatPrice`.
        // NOTE: This column is NOT badged: the panel groups nodes BY NAME (`firstEl` keeps
        // only the first element of each name), so two `StackV`s with the same name
        // would MERGE into one node and the tree would read wrong. The node that
        // matters inside the popover is `KeyValueList` — that one is badged; the
        // wrapping column is just `p-3` padding.
        // Two vertical rows inside a design (the eyebrow and the breakdown list) =
        // `grouped`, not `tight`. `tight` (1) is reserved for what sits INSIDE a
        // composite, e.g. the icon+label pair of `InlineIconLabel`.
        <StackV gap={1} principle="cell-pad"
            explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
            padding={4} isSkeleton={isSkeleton} items={[() => (
                <StackV gap={4} principle="label-field"
                    explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                    isSkeleton={isSkeleton} items={[
                        ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" text="Price breakdown" isSkeleton={isSkeleton} />,
                        // No `gap` passed: `KeyValueList` already owns its row rhythm (its own default
                        // is the §10b `grouped` step). Passing one from here overrides the composite's
                        // spacing from OUTSIDE, which §10 forbids — a composite owns its internal
                        // spacing and must not receive it.
                        ({ isSkeleton }: SkeletonProps) => (
                            <KeyValueList
                                isSkeleton={isSkeleton}
                                items={[
                                    {
                                        key: "list",
                                        label: "List price",
                                        value: formatPrice(original ?? discounted, currency),
                                    },
                                    ...(breakdown && original != null && original > breakdown.phase
                                        ? [{
                                            key: "phase",
                                            label: breakdown.phaseLabel ? `${breakdown.phaseLabel} phase` : "Phase discount",
                                            // NOTE: `KeyValueListItem.value` is now a plain `string` — this row
                                            // loses the `color="success-soft"` (green) tint it used to carry via
                                            // its own `Typography`. `KeyValueRow` only renders `value` through the
                                            // emphasis/plain split, no per-row tone prop. Preserving the green
                                            // accent needs either accepting the loss (done here) or a future
                                            // `tone`/`accent` field on `KeyValueListItem` — left for whoever owns
                                            // PriceTag/KeyValue next, not decided in this pass.
                                            value: `−${formatPrice(original - breakdown.phase, currency)} (−${phaseSave}%)`,
                                        }]
                                        : []),
                                    ...(breakdown && breakdown.loyaltyPercent > 0 && breakdown.phase > discounted
                                        ? [{
                                            key: "loyalty",
                                            label: breakdown.loyaltyNote ? `Loyalty discount · ${breakdown.loyaltyNote}` : "Loyalty discount",
                                            // See the "phase" row's note above — same loss of the green tint,
                                            // same reason.
                                            value: `−${formatPrice(breakdown.phase - discounted, currency)} (−${breakdown.loyaltyPercent}%)`,
                                        }]
                                        : []),
                                    {
                                        key: "total",
                                        label: "You pay",
                                        value: formatPrice(discounted, currency),
                                        // the TOTAL row: the frame handles the emphasis, replacing a hand-typed `border-t … pt-1`
                                        emphasis: true,
                                    },
                                ]}
                            />
                        ),
                    ]} />
            )]} />
    ) : null

    // The price row aligns on BASELINE (big number, struck number, chip share the
    // same text baseline) and wraps on its own when tight => exactly `Cluster`.
    // The three elements are THREE separate items, not merged into one
    // fragment — merging them leaves the frame's `gap` with nowhere to apply.
    const priceRow = (
        <Cluster
            gap={3}
            principle="value-row"
            align="baseline"

            items={[
                // The amount goes through the ATOM `Typography` (§9c), NOT raw
                // HeroUI — thanks to that, `isSkeleton` flows straight into it instead
                // of branching off to build a separate shimmer bar.
                () => (
                    <Typography
                        size={AMOUNT_TYPE[emphasis]}
                        weight="bold"
                        isSkeleton={isSkeleton}


                        text={formatPrice(discounted, currency)}
                    />
                ),
                ...(hasSaving
                    ? [() => (
                        <Typography
                            size={ORIGINAL_TYPE[emphasis]}
                            color="muted"
                            isSkeleton={isSkeleton}
                            isStruck


                            text={formatPrice(original, currency)}
                        />
                    )]
                    : []),
                // While resting: the chip still holds its place but is NOT wrapped in a
                // Popover — there's no data yet to open, and a pressable control while
                // loading is a false promise.
                ...(isSkeleton
                    ? [() => <Chip isSkeleton />]
                    : savePercent > 0
                        ? [() => (
                            <Popover>
                                <Popover.Trigger
                                    aria-label="Price breakdown"
                                    className="cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"

                                >
                                    {chip}
                                </Popover.Trigger>
                                <Popover.Content
                                    className="max-w-xs"

                                >
                                    {breakdownContent}
                                </Popover.Content>
                            </Popover>
                        )]
                        : []),
            ]}
        />
    )

    const savingLine = showSavingLine && (isSkeleton || hasSaving) ? (
        <Typography
            size="xs"
            color="muted"
            isSkeleton={isSkeleton}


            text={hasSaving ? `Save ${formatPrice(original - discounted, currency)}` : undefined}
        />
    ) : null

    return (
        // The outer column = two DIFFERENT lines (the price row · the "saving" line) =>
        // `StackV`, NOT `Cluster`: a cluster is ONE track of N PEER elements (§13b).
        <StackV
            // `grouped` (§10b): the price row and the saving line are two DIFFERENT vertical
            // rows of one design. It was `tight` (1), which §10b reserves for pairs sitting
            // inside a lower-tier component — the saving line read as if it were glued under the number.
            gap={4}
            classNames={classNames}
            isSkeleton={isSkeleton}
            items={[
                () => priceRow,
                () => savingLine,
            ]}
        />
    )
}

import React from "react"
import { CheckCircleIcon } from "@phosphor-icons/react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Breadcrumbs } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCardList } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ContentHeader` — the lesson-identity cluster atop the reading screen: a
 * `PageHeader` cluster carrying read state, reading time, challenge count, and
 * learning outcomes. One chip per cluster (`starci-fe/no-adjacent-chip`): read
 * state takes the chip, reading time and challenge count ride as muted text with
 * an inline icon. `isRead` is a state; losing the outcomes card and `isSkeleton`
 * are each their own leaf. The breadcrumb trail always exists.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface ContentHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** One line of "what you'll learn" — plain data, the block builds the row. */
export interface ContentHeaderOutcome {
    /** Stable React key. */
    key: string
    /** The outcome sentence, already localized by the caller (blocks carry no i18n). */
    text: string
}

/** Props for {@link ContentHeader}. */
export interface ContentHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<ContentHeaderCrumb>
    /** Lesson title. */
    title: string
    /** One-sentence summary of the lesson. */
    description?: string
    /**
     * `true` → the learner has finished this lesson. This is the ONE classifying
     * fact in the meta cluster, so it is the one that gets a chip.
     */
    isRead?: boolean
    /** Estimated reading time in MINUTES — the block adds the word itself. */
    minutesRead?: number
    /** How many challenges hang off this lesson — the block adds the word itself. */
    challengeCount?: number
    /**
     * The "what you'll learn" lines. Empty or omitted → the whole section is not
     * drawn at all: a lesson with no stated outcomes should say nothing, not show
     * an empty card.
     */
    outcomes?: Array<ContentHeaderOutcome>
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c), so the shimmer keeps the exact box of the thing it replaces.
     */
    isSkeleton?: boolean
}

/**
 * Lesson identity cluster at the top of the reading screen. See the file header
 * for the full contract.
 *
 * @param props - {@link ContentHeaderProps}
 */
const ContentHeader = ({
    breadcrumbItems,
    title,
    description,
    isRead = false,
    minutesRead,
    challengeCount,
    outcomes,
    isSkeleton = false,
}: ContentHeaderProps) => {
    const hasOutcomes = isSkeleton || (outcomes?.length ?? 0) > 0

    return (
        <div>
            <StackV
                gap={6}
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <PageHeader

                            isSkeleton={isSkeleton}
                            breadcrumb={() =>
                                isSkeleton || breadcrumbItems?.length ? (
                                    <div className="w-fit">
                                        <Breadcrumbs
                                            collapseOnMobile
                                            collapseFrom={4}
                                            items={breadcrumbItems ?? []}
                                            isSkeleton={isSkeleton}
                                        />
                                    </div>
                                ) : undefined
                            }
                            title={title}
                            description={description}
                            meta={() =>
                                <StackH
                                    gap={3}
                                    align="center"
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                    isSkeleton={isSkeleton}
                                    items={[
                                        ...(isSkeleton ? [() => (
                                            <Chip isSkeleton />
                                        )] : isRead ? [() => (
                                            <Chip
                                                tone="success"
                                                icon={CheckCircleIcon}
                                                text="Read"

                                            />
                                        )] : []),
                                        ...(isSkeleton ? [() => (
                                            <Typography size="xs" color="muted" isSkeleton />
                                        )] : [
                                            ...(minutesRead != null ? [() => (
                                                <Typography
                                                    size="xs"
                                                    color="muted"
                                                    text={`${minutesRead} min read`}

                                                />
                                            )] : []),
                                            ...(challengeCount != null ? [() => (
                                                <Typography
                                                    size="xs"
                                                    color="muted"
                                                    text={`${challengeCount} challenges`}

                                                />
                                            )] : []),
                                        ]),
                                    ]}
                                />
                            }
                        />
                    ),
                    ...(hasOutcomes ? [() => (
                        <SurfaceCardList
                            label="What you will learn"
                            isSkeleton={isSkeleton}

                            items={(outcomes ?? []).map((outcome) => ({
                                key: outcome.key,
                                leadingIcon: CheckCircleIcon,
                                leadingIconColor: "success",
                                title: outcome.text,
                            }))}
                        />
                    )] : []),
                ]}
            />
        </div>
    )
}

export { ContentHeader }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { ProgressMeter } from "@sb-components/composites/stats/ProgressMeter/ProgressMeter"
import { ListMeta } from "@sb-components/composites/lists/List/List"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { type ContinueCardDataProps } from "./types"

/** Shared internals: eyebrow-less, title → meta/subtitle → progress → CTA. */
export const CardBody = ({
    title,
    subtitle,
    value,
    max = 100,
    meta,
    timeLeft,
    urgent = false,
    isSkeleton = false,
    cta,
}: ContinueCardDataProps & { cta: React.ReactNode }) => {
    return (
        <>
            {/* The outer row = ONE horizontal track ⇒ `StackH` (children are ARBITRARY, not a
                repeating list so NOT `Cluster`). The inner column = a vertical track ⇒ `StackV`.
                `min-w-0 flex-1` stays in `className`: that's its PLACEMENT within the parent row
                (`className` is allowed for placement), not the scaffold's own shape. */}
            <div className="relative">
                <StackH
                    gap={4}
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    align="center"
                    isSkeleton={isSkeleton}
                    items={[
                        ({ isSkeleton }: SkeletonProps) => (
                            <StackV
                                gap={3}
                                classNames={["min-w-0", "flex-1"]}
                                isSkeleton={isSkeleton}
                                items={[
                                    () => (
                                        <Typography weight="medium" truncate isSkeleton={isSkeleton} text={title} />
                                    ),
                                    ...(isSkeleton ? [() => (
                                        // `ListMeta` (the scaffold the live branch uses here) has no `isSkeleton`
                                        // yet and sits outside this round's boundary — CardBody calls that scaffold
                                        // DIRECTLY so it builds ONE shimmer bar in place of the meta/subtitle row
                                        // (the real shape always has EXACTLY ONE of the two) using atom `Typography`.
                                        <Typography size="xs" color="muted" isSkeleton />
                                    )] : meta?.length || timeLeft ? [() => (
                                        <ListMeta
                                            items={meta ?? []}

                                            chip={
                                                timeLeft ? (
                                                    // Same kind of information (time left) ⇒ the same element in
                                                    // EVERY case; only the TONE escalates: `default` while time
                                                    // remains, `warning` when it's about to run out.
                                                    () => (
                                                        <Chip
                                                            tone={urgent ? "warning" : "default"}

                                                            text={timeLeft}
                                                        />
                                                    )
                                                ) : undefined
                                            }
                                        />
                                    )] : subtitle ? [() => (
                                        <Typography size="xs" color="muted" truncate text={subtitle} />
                                    )] : []),
                                ]}
                            />
                        ),
                    ]}
                />
            </div>
            {/* Progress SITS right under the text cluster, BEFORE the button:
            where am I → how much progress → what's next. Put it
            after the CTA and it reads as detached from the card, misread as belonging to the block below. */}
            {value === undefined ? null : isSkeleton ? (
                // `ProgressMeter` (scaffold) has no `isSkeleton` yet and sits outside this
                // round's boundary — CardBody calls that scaffold directly so it builds a
                // track shimmer bar matching the real track height (`h-1`, see `ProgressMeter.tsx`).
                <HeroSkeleton className="h-1 w-full rounded-full" />
            ) : (
                <ProgressMeter value={value} max={max} />
            )}
            <div className="relative">{cta}</div>
        </>
    )
}

import React from "react"
import { CaretRightIcon, CardsIcon, MagnifyingGlassIcon, RowsIcon, SquaresFourIcon } from "@phosphor-icons/react"
import { InputSearch } from "@sb-components/atoms/forms"
import { Tabs, type TabItem } from "@sb-components/atoms/navigation/Tabs/Tabs"
import { Pagination } from "@sb-components/atoms/navigation/Pagination/Pagination"
import { ProgressGauge } from "@sb-components/atoms/display/Progress/Progress"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import {
    SurfaceCard,
    SurfaceCardList,
    type SurfaceCardListItem,
} from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { AsyncContentEmpty } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { Grid, type GridItem } from "@sb-components/frames/Grid/Grid"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
import { VariantChipDifficulty, type Difficulty } from "@sb-components/starci/blocks/learn/VariantChip/VariantChip"

/**
 * `FlashcardDeckList` — the course's deck picker: search, switch between a grid
 * of tiles and a scan-friendly line list, page through results, and open any
 * deck. Four leaves: `GridView` (tiles in a responsive `Grid`), `LineView`
 * (rows in one `SurfaceCardList`), `SearchEmpty` (`AsyncContentEmpty`,
 * view-agnostic), and `Loading` (a guessed tile count through each composite's
 * mirror). Toggling `view` or `isSkeleton` on a populated list repaints the same
 * tree.
 */

/** How the deck track is currently laid out. Persisted by the caller, not a leaf-driving prop by itself (see file header). */
export type FlashcardDeckListView = "grid" | "line"

/** One deck row/tile — plain DATA; the block decides which chips and meters it earns. */
export interface FlashcardDeckListDeck {
    /** Stable id — the React key, and what `onSelectDeck` fires with. */
    id: string
    /** Deck title. */
    title: string
    /** Optional blurb. Grid: clamped to two lines. Line: the row's subtitle (falls back to a card count when absent). */
    description?: string
    /** Difficulty tier — the block builds `VariantChipDifficulty` itself. */
    difficulty: Difficulty
    /** Cards due for review right now. Omit or `0` → no due chip (see file header). */
    dueCount?: number
    /** Cards the viewer has already mastered. Paired with `totalCount` for the mastery meter. */
    masteredCount?: number
    /** Total cards in the deck. */
    totalCount: number
}

/** Props for {@link FlashcardDeckList}. */
export interface FlashcardDeckListProps {
    /** The current page's decks, in display order. */
    decks: Array<FlashcardDeckListDeck>
    /** Current search text (controlled). */
    query: string
    /** Fired on every keystroke in the search field. */
    onQueryChange: (query: string) => void
    /** Which shape the track renders as — a persisted VIEWER SETTING, not a one-off UI toggle. */
    view: FlashcardDeckListView
    /** Fired with the shape the viewer picked. */
    onViewChange: (view: FlashcardDeckListView) => void
    /** 1-based current page. */
    page: number
    /** Total page count — see the file header's "added prop" note. */
    totalPages: number
    /** Fired with the 1-based page the viewer picked. */
    onPageChange: (page: number) => void
    /** Fired with a deck's id when its tile/row is pressed. */
    onSelectDeck: (id: string) => void
    /** Overrides the default grid-tile CTA wording ("Study now"). Localization override, not domain data (mirrors `seeMoreLabel`/`removeLabel`). */
    ctaLabel?: string
    /** `true` → grid tiles and list rows also carry the per-viewer mastery meter. `false` → a plain browse surface with no progress talk. */
    showProgress: boolean
    /** `true` → the track renders its own mirror. `decks` empty while on → guesses a placeholder count in the current `view`'s shape (§12c). */
    isSkeleton?: boolean
}

/** The block's own wording for the grid-tile CTA — overridable via `ctaLabel`. */
const DEFAULT_CTA_LABEL = "Study now"

/** View-toggle tabs — icon only, labels are `sr-only` (the atom takes a `ReactNode` label, so this is within its own contract, not a hack around it). */
const VIEW_ITEMS: Array<TabItem> = [
    { key: "grid", label: <span className="sr-only">Grid view</span>, icon: SquaresFourIcon },
    { key: "line", label: <span className="sr-only">List view</span>, icon: RowsIcon },
]

/** Placeholder rows/tiles for the guessed skeleton count (§12c) — never carry a press handler. */
const skeletonDecks = (count: number): Array<FlashcardDeckListDeck> =>
    Array.from({ length: count }, (_unused, index) => ({
        id: `skeleton-${index}`,
        title: "",
        difficulty: "beginner" as Difficulty,
        totalCount: 0,
    }))

/**
 * The block's decision at a glance:
 * ─────────────────────────────────────────────────────────────────────────────
 * DECIDE → track is empty (search or fetch found nothing) → LEAF 3, everything below skipped
 *        → still no decks AND still loading           → LEAF 4, placeholder count
 *        → view === "grid"                            → LEAF 1
 *        → view === "line"                             → LEAF 2
 * ─────────────────────────────────────────────────────────────────────────────
 *
 * @param props - {@link FlashcardDeckListProps}
 */
const FlashcardDeckList = ({
    decks,
    query,
    onQueryChange,
    view,
    onViewChange,
    page,
    totalPages,
    onPageChange,
    onSelectDeck,
    ctaLabel,
    showProgress,
    isSkeleton = false,
}: FlashcardDeckListProps) => {
    // Empty while loading (no real decks yet) → guess a placeholder count in the
    // CURRENT view's shape, keeping the right footprint for when real data lands
    // (§8). Once real `decks` exist, keep the exact count already there.
    const usingPlaceholders = isSkeleton && decks.length === 0
    const source = usingPlaceholders ? skeletonDecks(view === "grid" ? 6 : 4) : decks

    // LEAF 3 — the whole track is replaced by the message; nothing below runs.
    // Reached whether `view` is grid or line, so it forks on data, not on shape.
    const isEmpty = !isSkeleton && decks.length === 0
    const hasQuery = query.trim().length > 0

    /** One grid tile's content — computed only when it will actually render (skeleton tiles never see it). */
    const deckTileBody = (deck: FlashcardDeckListDeck) => {
        const chips: Array<ComponentTypeWithSkeleton> = [
            () => <VariantChipDifficulty difficulty={deck.difficulty} />,
        ]
        if (deck.dueCount) {
            chips.push(() => <Chip tone="warning" text={`${deck.dueCount} due`} />)
        }

        return (
            <StackV
                gap={3}
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <StackV
                            gap={1}
                            isSkeleton={isSkeleton}
                            items={[
                                () => <Typography size="sm" weight="medium" truncate text={deck.title} />,
                                ...(deck.description ? [() => (
                                    <Typography size="xs" color="muted" lineClamp={2} text={deck.description} />
                                )] : []),
                            ]}
                        />
                    ),
                    () => <Cluster gap={3} items={chips} />,
                    ...(showProgress && deck.totalCount > 0 ? [() => (
                        <StackH
                            gap={2}
                            isSkeleton={isSkeleton}
                            items={[
                                () => (
                                    <div className="flex-1">
                                        <ProgressGauge
                                            value={((deck.masteredCount ?? 0) / deck.totalCount) * 100}
                                            size="sm"
                                            ariaLabel={`Mastery level for the ${deck.title} deck`}

                                        />
                                    </div>
                                ),
                                () => (
                                    <Typography
                                        size="xs"
                                        color="muted"
                                        text={`${deck.masteredCount ?? 0}/${deck.totalCount}`}

                                    />
                                ),
                            ]}
                        />
                    )] : []),
                    () => (
                        <StackH
                            gap={2}
                            principle="icon-text"
                            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                            justify="end"
                            isSkeleton={isSkeleton}
                            items={[
                                () => (
                                    <Typography
                                        size="sm"
                                        weight="medium"
                                        color="accent-soft"
                                        text={ctaLabel ?? DEFAULT_CTA_LABEL}

                                    />
                                ),
                                () => (
                                    <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4 shrink-0 text-accent-soft-foreground" />
                                ),
                            ]}
                        />
                    ),
                ]}
            />
        )
    }

    const tiles: Array<GridItem> = source.map((deck) => ({
        key: deck.id,
        content: () => (
            <div>
                <SurfaceCard
                    isSkeleton={isSkeleton}
                    // Always set, even during a placeholder tile: `Base`'s skeleton-mirror
                    // branch intercepts BEFORE this ever reaches a real button (see
                    // SurfaceCard.tsx), so it's inert while `isSkeleton` is true — it only
                    // needs to be present so the merged `.Pressable` shape (not the plain
                    // `SurfaceCard` shape) is the one that renders once loading finishes.
                    onPress={() => onSelectDeck(deck.id)}
                    ariaLabel={deck.title}

                    body={() => (isSkeleton ? null : deckTileBody(deck))}
                />
            </div>
        ),
    }))

    const rows: Array<SurfaceCardListItem> = source.map((deck) => {
        const metaChips: Array<ComponentTypeWithSkeleton> = []
        if (!isSkeleton) {
            metaChips.push(() => <VariantChipDifficulty difficulty={deck.difficulty} />)
            if (deck.dueCount) {
                metaChips.push(() => <Chip tone="warning" text={`${deck.dueCount} due`} />)
            }
        }
        return {
            key: deck.id,
            leadingIcon: CardsIcon,
            title: deck.title,
            // The block owns this fallback (§14d.1): a deck with no blurb still says
            // something useful — its card count — instead of a blank second line.
            subtitle: deck.description ?? `${deck.totalCount} cards`,
            meta: metaChips.length > 0 ? () => <Cluster gap={3} items={metaChips} /> : undefined,
            trailing:
                showProgress && !isSkeleton && deck.totalCount > 0
                    ? () => <Typography size="xs" color="muted" text={`${deck.masteredCount ?? 0}/${deck.totalCount}`} />
                    : undefined,
            onPress: usingPlaceholders ? undefined : () => onSelectDeck(deck.id),
        }
    })

    const track = isEmpty ? (
        <AsyncContentEmpty
            icon={hasQuery ? MagnifyingGlassIcon : undefined}
            title={hasQuery ? `No decks match “${query}”` : "This course has no decks yet"}
            description={hasQuery ? "Try a different search term." : undefined}


        />
    ) : view === "grid" ? (
        <div>
            <Grid columns={{ base: 1, sm: 2, md: 3 }} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={tiles}  />
        </div>
    ) : (
        <SurfaceCardList isSkeleton={isSkeleton} items={rows} />
    )

    return (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <StackH
                        gap={3}
                        principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        at="sm"
                        isSkeleton={isSkeleton}
                        items={[
                            () => (
                                <div className="min-w-0 flex-1">
                                    <InputSearch
                                        value={query}
                                        onValueChange={onQueryChange}
                                        placeholder="Search decks"
                                        ariaLabel="Search decks"

                                    />
                                </div>
                            ),
                            () => (
                                <div>
                                    <Tabs
                                        items={VIEW_ITEMS}
                                        selectedKey={view}
                                        onSelectionChange={(key) => onViewChange(key as FlashcardDeckListView)}
                                        ariaLabel="Display style"

                                    />
                                </div>
                            ),
                        ]}
                    />
                ),
                () => track,
                ...(!isSkeleton && decks.length > 0 ? [() => (
                    <div>
                        <Pagination currentPage={page} totalPages={totalPages} onPageChange={onPageChange} />
                    </div>
                )] : []),
            ]}
        />
    )
}

export { FlashcardDeckList }

import React from "react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Breadcrumbs } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { EnumChip, type EnumChipEntry } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `FoundationHeader` — the identity cluster at the top of a foundation resource's
 * page: breadcrumb trail, title, description, and a meta row carrying the
 * resource's kind, its recommended flag, its tags, and its author attribution.
 * Two chips (kind and "recommended") both classify the resource. Every optional
 * part — recommended chip, tag row, author line, skeleton — is a data condition
 * on the same trail → title → description → meta shape.
 */

/** Resource kind of a foundation item — mirrors `src`'s `FoundationKind` enum (closed to 3 values). */
export enum FoundationKind {
    /** An external hyperlink (e.g. official docs, article on another site). */
    ExternalLink = "external_link",
    /** An embedded or linked video resource. */
    Video = "video",
    /** A document or written guide, rendered as markdown. */
    Document = "document",
}

/**
 * Kind → chip presentation. EXHAUSTIVE `Record` (not `Partial`, unlike the
 * type `EnumChip` itself accepts): the enum is closed to 3 values, so the
 * compiler must refuse a build that adds a kind and forgets its entry here.
 * The block owns this table (§14d.1: no caller-supplied color/label).
 */
const KIND_MAP: Record<FoundationKind, EnumChipEntry> = {
    [FoundationKind.ExternalLink]: { color: "accent", label: "External link" },
    [FoundationKind.Video]: { color: "accent", label: "Video" },
    [FoundationKind.Document]: { color: "accent", label: "Article" },
}

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface FoundationHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** One topic tag on a foundation resource — plain data, the block builds the chip. */
export interface FoundationHeaderTag {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
}

/** Props for {@link FoundationHeader}. */
export interface FoundationHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. A foundation resource is always reached through its category, so the trail is always required (same call `ModuleHeader` makes for its own always-present trail). */
    breadcrumbItems: Array<FoundationHeaderCrumb>
    /** Resource title. */
    title: string
    /** One-sentence summary of the resource. */
    description?: string
    /** Resource kind — the ONE required classifying fact, drives the `EnumChip` tone + label. */
    kind: FoundationKind
    /** `true` → the resource is editorially highlighted; renders a second, success-toned chip beside the kind chip. */
    isRecommended?: boolean
    /** Topic tags. Empty or omitted → no tag chips render. */
    tags?: Array<FoundationHeaderTag>
    /** Author or source attribution — the block adds "Author: — itself. Omit or empty → no author line. */
    author?: string
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The foundation-resource identity cluster at the top of a resource's own
 * page. See the file header for the full contract and why this is a sibling
 * of `ContentHeader`/`ModuleHeader`/`CourseBrief` rather than an edit of any
 * of them.
 *
 * @param props - {@link FoundationHeaderProps}
 */
const FoundationHeader = ({
    breadcrumbItems,
    title,
    description,
    kind,
    isRecommended = false,
    tags,
    author,
    isSkeleton = false,
}: FoundationHeaderProps) => {
    const hasTags = (tags?.length ?? 0) > 0
    const hasAuthor = author != null && author.trim().length > 0

    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() => (
                    <div className="w-fit">
                        <Breadcrumbs
                            collapseOnMobile
                            collapseFrom={4}
                            items={breadcrumbItems}
                            isSkeleton={isSkeleton}
                        />
                    </div>
                )}
                title={title}
                description={description}
                meta={() =>
                    <StackV
                        gap={4}
                        isSkeleton={isSkeleton}
                        items={[
                            () => (
                                <StackH
                                    gap={3}
                                    principle="chip-row"
                                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                    align="center"
                                    at="sm"
                                    isSkeleton={isSkeleton}
                                    items={[
                                        () => (
                                            <EnumChip
                                                value={isSkeleton ? FoundationKind.Document : kind}
                                                map={KIND_MAP}
                                                isSkeleton={isSkeleton}

                                            />
                                        ),
                                        ...(isSkeleton
                                            ? [() => <Chip isSkeleton />]
                                            : isRecommended
                                                ? [() => <Chip tone="success" text="Recommended" />]
                                                : []),
                                        ...(isSkeleton
                                            ? [() => <Chip isSkeleton />, () => <Chip isSkeleton />]
                                            : hasTags
                                                ? (tags ?? []).map((tag) => () => <Chip text={tag.label} />)
                                                : []),
                                    ]}
                                />
                            ),
                            ...(isSkeleton ? [() => (
                                <Typography size="xs" color="muted" isSkeleton />
                            )] : hasAuthor ? [() => (
                                <Typography
                                    size="xs"
                                    color="muted"
                                    text={`Author: ${author}`}

                                />
                            )] : []),
                        ]}
                    />
                }
            />
        </div>
    )
}

export { FoundationHeader }

import React from "react"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV, StackH } from "@sb-components/frames/Stack/Stack"
import { type LeaderboardPodiumEntry } from "../types"

/** Visual order left→right on the dais: 2nd, 1st (centre), 3rd. */
const PODIUM_VISUAL_ORDER: Record<1 | 2 | 3, number> = { 2: 1, 1: 2, 3: 3 }
/** Riser height by rank — 1st tallest, so the dais itself carries the ranking, not just a label. */
const PODIUM_RISER_HEIGHT: Record<1 | 2 | 3, string> = { 1: "h-20", 2: "h-14", 3: "h-10" }

/** Props for the internal {@link Podium} piece. */
interface PodiumProps {
    /** Top-3 finishers, in any order. */
    entries: Array<LeaderboardPodiumEntry>
    /** Accessible tag for "this is you", forwarded from the block. */
    meLabel: string
    isSkeleton: boolean
}

/** One podium dais entry: avatar, username, score line, ranked riser. */
const podiumEntryCard = (entry: LeaderboardPodiumEntry, meLabel: string, isSkeleton: boolean) => {
    const riser = (
        <div className={`flex w-full items-center justify-center rounded-t-xl bg-accent-soft ${PODIUM_RISER_HEIGHT[entry.rank]}`}>
            {/* real `src` (`Podium/index.tsx:103-112`): the rank number is a BARE div,
                declaring no size at all (inherits base/16px), just `font-bold` — not `lg`. */}
            <Typography
                size="base"
                weight="bold"
                tabularNums
                isSkeleton={isSkeleton}
                text={isSkeleton ? undefined : String(entry.rank)}
                color="accent-soft"

            />
        </div>
    )
    return (
        <div key={entry.rank} className="w-24">
            <StackV
                gap={2}
                principle="title-subtitle"
                explain="Title over supporting line — not label-field, because neither line is a form control label."
                align="center"
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <div>
                            <Avatar
                                name={entry.username}
                                src={entry.avatar ?? undefined}
                                seed={entry.username}
                                size={entry.rank === 1 ? "lg" : "md"}
                                isSkeleton={isSkeleton}

                            />
                        </div>
                    ),
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            color={entry.isMe ? "accent" : undefined}
                            truncate
                            align="center"
                            isSkeleton={isSkeleton}
                            text={isSkeleton ? undefined : entry.username}


                        />
                    ),
                    () => (
                        <Typography
                            size="xs"
                            color="muted"
                            isSkeleton={isSkeleton}
                            text={isSkeleton ? undefined : entry.pointsLabel}

                        />
                    ),
                    () => riser,
                    ...(entry.isMe ? [() => <span className="sr-only">{meLabel}</span>] : []),
                ]}
            />
        </div>
    )
}

/** One podium dais entry: avatar, username, score line, ranked riser. */
export const Podium = ({ entries, meLabel, isSkeleton }: PodiumProps) => (
    <StackH
        gap={3}
        principle="sibling-stack"
        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
        justify="center"
        align="end"
        isSkeleton={isSkeleton}
        items={[...entries]
            .sort((a, b) => PODIUM_VISUAL_ORDER[a.rank] - PODIUM_VISUAL_ORDER[b.rank])
            .map((entry) => () => podiumEntryCard(entry, meLabel, isSkeleton))}
    />
)

import React from "react"
import { ClockIcon, PuzzlePieceIcon, StackIcon } from "@phosphor-icons/react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Breadcrumbs } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { EnumChip, type EnumChipEntry } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { HighlightChip } from "@sb-components/composites/chips/HighlightChip/HighlightChip"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { StackH } from "@sb-components/frames/Stack/Stack"

/**
 * `ModuleHeader` — the module-identity cluster at the top of a module's page,
 * answering "what is this module, and how big is it". Sibling of `ContentHeader`
 * and `CourseBrief`: places identity into `PageHeader`, but carries a module's tier
 * plus three `HighlightChip` counts (lessons, minutes, challenges) — the counts are
 * the headline figures, so they keep their chip shape while `tier` classifies the
 * module. Which chips draw stays states of one shape; losing the whole meta row
 * drops a `PageHeader` region and earns its own shape.
 */

/** Learning tier of a module — mirrors the `src` `CourseContentTier` enum (GraphQL / DB, shared across every course). */
export enum CourseContentTier {
    /** Entry-level material — always free. */
    Foundation = "foundation",
    /** Mid-level material — the later half is premium. */
    Intermediate = "intermediate",
    /** Advanced material — always premium. */
    Advanced = "advanced",
}

/** Tier → chip presentation. The block owns this table (§14d.1: no caller-supplied color/label). */
const TIER_MAP: Record<CourseContentTier, EnumChipEntry> = {
    [CourseContentTier.Foundation]: { color: "success", label: "Foundation" },
    [CourseContentTier.Intermediate]: { color: "warning", label: "Intermediate" },
    [CourseContentTier.Advanced]: { color: "danger", label: "Advanced" },
}

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface ModuleHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** Props for {@link ModuleHeader}. */
export interface ModuleHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. A module is always reached through its course, so the trail is always required (no "no breadcrumb" case, same call `ContentHeader` makes). */
    breadcrumbItems: Array<ModuleHeaderCrumb>
    /** Module title. */
    title: string
    /** One-sentence summary of the module. */
    description?: string
    /** Learning tier — the ONE classifying fact, drives the `EnumChip` tone + label. Omit → no tier chip. */
    tier?: CourseContentTier
    /** How many lessons this module has — the block adds "lessons" itself. Omit or `0` → no chip. */
    lessonCount?: number
    /** Total reading/study minutes across the module — the block adds "minutes of study" itself. Omit or `0` → no chip. */
    minutesTotal?: number
    /** How many challenges hang off this module — the block adds "challenges" itself. Omit or `0` → no chip. */
    challengeCount?: number
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The module identity cluster at the top of a module's own page. See the file
 * header for the full contract and why this is a sibling of `ContentHeader`/
 * `CourseBrief` rather than an edit of either.
 *
 * @param props - {@link ModuleHeaderProps}
 */
const ModuleHeader = ({
    breadcrumbItems,
    title,
    description,
    tier,
    lessonCount,
    minutesTotal,
    challengeCount,
    isSkeleton = false,
}: ModuleHeaderProps) => {
    const hasLessons = (lessonCount ?? 0) > 0
    const hasMinutes = (minutesTotal ?? 0) > 0
    const hasChallenges = (challengeCount ?? 0) > 0
    // The meta row only exists once it has something to show — otherwise `PageHeader`
    // gets `undefined` and drops the whole slot instead of an empty row with nothing in it.
    const hasMeta = isSkeleton || tier != null || hasLessons || hasMinutes || hasChallenges

    const metaRow = hasMeta ? (
        <StackH
            gap={3}
            align="center"
            at="sm"
            principle="chip-row"
            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
            isSkeleton={isSkeleton}

            items={[
                () => (isSkeleton ? (
                    <EnumChip
                        value={CourseContentTier.Foundation}
                        map={TIER_MAP}
                        isSkeleton

                    />
                ) : tier != null ? (
                    <EnumChip value={tier} map={TIER_MAP} />
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={StackIcon} />
                    </span>
                ) : hasLessons ? (
                    <span>
                        <HighlightChip
                            icon={StackIcon}
                            value={lessonCount}
                            label="lessons"
                        />
                    </span>
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={ClockIcon} />
                    </span>
                ) : hasMinutes ? (
                    <span>
                        <HighlightChip
                            icon={ClockIcon}
                            value={minutesTotal}
                            label="minutes"
                        />
                    </span>
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={PuzzlePieceIcon} />
                    </span>
                ) : hasChallenges ? (
                    <span>
                        <HighlightChip
                            icon={PuzzlePieceIcon}
                            value={challengeCount}
                            label="challenges"
                        />
                    </span>
                ) : null),
            ]}
        />
    ) : undefined

    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() => (
                    <div className="w-fit">
                        <Breadcrumbs
                            collapseOnMobile
                            collapseFrom={4}
                            items={breadcrumbItems}
                            isSkeleton={isSkeleton}
                        />
                    </div>
                )}
                title={title}
                description={description}
                meta={() => metaRow}
            />
        </div>
    )
}

export { ModuleHeader }

import React from "react"
import { GithubLogoIcon } from "@phosphor-icons/react"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { Breadcrumbs, type BreadcrumbItem } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { AsyncContent, type AsyncContentEmptyProps } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { ProgressMeter } from "@sb-components/composites/stats/ProgressMeter/ProgressMeter"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Grid } from "@sb-components/frames/Grid/Grid"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { ContinueCardHero, ContinueCardItem } from "@sb-components/starci/blocks/learn/ContinueCard/ContinueCard"

/**
 * `PersonalProjectDashboard` — the capstone landing overview ("where am I + what's
 * next"), shown when the personal-project route carries no `taskId`: breadcrumb →
 * title/description/GitHub-status header, over a continue hero + completion meter,
 * over the current milestone's tasks as a two-column grid.
 *
 * Shapes:
 *   • `Full` — a next task exists, so the continue hero renders; GitHub connected
 *     vs not are states inside it.
 *   • `AllDone` — no `currentTask`, so the hero is gone, replaced by an "all done" line.
 *   • `Loading` — `AsyncContent` falls to the shimmer mirror.
 *   • `Empty` — `AsyncContent` falls to the empty message; the header is unaffected.
 */

/** One breadcrumb link above the dashboard title — plain data, the block builds the atom. */
export interface PersonalProjectDashboardCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** GitHub connection status fed into the header's status chip. */
export interface PersonalProjectGithubStatus {
    /** `true` → the chip renders in its connected (success) tone. */
    isConnected: boolean
    /**
     * Already-formatted display text — `"owner/repo · branch"` when connected, or
     * the "not connected" copy otherwise. Parsing the raw GitHub URL is the
     * caller's job (business logic, not presentation); the block only reacts to
     * `isConnected` for the chip's tone/icon.
     */
    label: string
}

/** The task currently in progress, fed into the continue hero. */
export interface PersonalProjectCurrentTask {
    /** 1-based position inside its milestone — the block prefixes it onto the title. */
    sortIndex: number
    /** Task title, WITHOUT the index prefix. */
    title: string
}

/** Where one keep-going task stands — the block owns the subtitle wording per state. */
export type PersonalProjectTaskSubtitleState = "active" | "done" | "locked" | "todo"

/** One task row in the keep-going grid — plain data, the block builds the tile. */
export interface PersonalProjectDashboardTask {
    /** Stable React key + the id handed back to `onSelectTask`. */
    id: string
    /** 1-based position inside the milestone — the block prefixes it onto the title. */
    sortIndex: number
    /** Task title, WITHOUT the index prefix. */
    title: string
    /** Which subtitle line this row shows — see {@link PersonalProjectTaskSubtitleState}. */
    subtitleState: PersonalProjectTaskSubtitleState
}

/** Aggregate KPIs across the whole capstone, shown under the completion meter. */
export interface PersonalProjectStats {
    /** Tasks completed so far. */
    done: number
    /** Tasks in the whole project. */
    total: number
    /** Total submit attempts across every task. */
    attempts: number
    /**
     * Already-formatted average score, e.g. `"18/20"` or `"—"` with no scored
     * attempts yet — computing the fraction is arithmetic the caller already
     * has to do to pick the "—" fallback, so it stays one string, same as
     * `ContentLanguage.label`.
     */
    avgLabel: string
}

/** Props for {@link PersonalProjectDashboard}. */
export interface PersonalProjectDashboardProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<PersonalProjectDashboardCrumb>
    /** Dashboard title, e.g. "Personal Project". */
    title: string
    /** One-line description under the title. */
    description?: string
    /** GitHub connection status shown as a chip in the header's meta row. */
    githubStatus: PersonalProjectGithubStatus
    /** The next task to work on. Omit once every task is completed. */
    currentTask?: PersonalProjectCurrentTask
    /** Fired when the learner presses the continue hero's CTA. */
    onContinue: () => void
    /** The current milestone's name — the block prefixes "Continue ·" onto it. */
    milestoneLabel?: string
    /** The current milestone's tasks, in display order. */
    tasks: Array<PersonalProjectDashboardTask>
    /** Fired with a task's id when its tile is pressed. */
    onSelectTask: (taskId: string) => void
    /** Aggregate KPIs — see {@link PersonalProjectStats}. */
    stats: PersonalProjectStats
    /**
     * `true` while the milestone/progress fetch is running (no cache yet) — the
     * continue hero + progress stats + keep-going grid fall to their shimmer
     * mirror. The header (trail/title/description) is unaffected: it never
     * waits on this fetch.
     */
    isLoading?: boolean
    /**
     * `true` → the course has no milestones/tasks configured at all. Only takes
     * effect once `isLoading` is false.
     */
    isEmpty?: boolean
    /**
     * `true` → the header's own dynamic part (the GitHub chip) mirrors instead
     * of waiting on data — independent of `isLoading`, since that chip's data
     * comes off the enrollment record, not the milestone fetch.
     */
    isSkeleton?: boolean
}

/** Block-owned constant — the one classifying fact of the continue hero's subtitle. */
const NEXT_TASK_SUBTITLE = "Next task"

/** Block-owned constant — shown instead of the hero once every task is done. */
const ALL_DONE_TEXT = "You've completed every task in your personal project"

/** Block-owned constant — the completion meter's own label. */
const PROGRESS_LABEL = "Completion progress"

/** Block-owned constant — the keep-going grid's heading prefix. */
const KEEP_GOING_PREFIX = "Continue"

/** Block-owned wording per {@link PersonalProjectTaskSubtitleState} — the caller only sends the enum. */
const TASK_SUBTITLE: Record<PersonalProjectTaskSubtitleState, string> = {
    active: "Next task",
    done: "Completed",
    locked: "Locked",
    todo: "Not started",
}

/** Block-owned empty-state copy — the course has no capstone tasks configured yet. */
const EMPTY_STATE: AsyncContentEmptyProps = {
    title: "No tasks yet",
    description: "This course's personal project has no milestones/tasks set up yet.",
}

/** Placeholder shape guessed while loading (§12c) — mirrors `src`'s 4-row skeleton. */
const SKELETON_TASKS: Array<PersonalProjectDashboardTask> = Array.from({ length: 4 }, (_unused, index) => ({
    id: `skeleton-${index}`,
    sortIndex: index + 1,
    title: "",
    subtitleState: "todo",
}))

/** Assembles the milestone-name prefix the same way `KeepGoingPath` assembles its own heading. */
const keepGoingLabel = (milestoneLabel: string | undefined) =>
    milestoneLabel ? `${KEEP_GOING_PREFIX} · ${milestoneLabel}` : KEEP_GOING_PREFIX

/** Assembles the block-owned stats sentence under the completion meter. */
const statsLine = (stats: PersonalProjectStats) =>
    `${stats.done}/${stats.total} tasks completed · ${stats.attempts} submissions · average score ${stats.avgLabel}`

/** Props for the internal {@link Body} — the two async leaves, real or their shimmer guess. */
interface BodyProps {
    currentTask?: PersonalProjectCurrentTask
    onContinue: () => void
    milestoneLabel?: string
    tasks: Array<PersonalProjectDashboardTask>
    onSelectTask: (taskId: string) => void
    stats: PersonalProjectStats
    isSkeleton: boolean
}

/**
 * `ContinueHero+ProgressStats` and `KeepGoingGrid` — built ONCE and reused for
 * both the real content branch and the loading mirror (guessed data + forced
 * `isSkeleton`), so the two never drift into two hand-kept shapes.
 */
const Body = ({
    currentTask,
    onContinue,
    milestoneLabel,
    tasks,
    onSelectTask,
    stats,
    isSkeleton,
}: BodyProps) => {
    const heroSection = (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}

            items={[
                () => (isSkeleton || currentTask ? (
                    <ContinueCardHero
                        title={currentTask ? `${currentTask.sortIndex}. ${currentTask.title}` : ""}
                        subtitle={NEXT_TASK_SUBTITLE}
                        isSkeleton={isSkeleton}
                        onPress={onContinue}


                    />
                ) : (
                    <Typography weight="semibold" text={ALL_DONE_TEXT} />
                )),
                () => (
                    <ProgressMeter
                        value={stats.done}
                        max={stats.total || 1}
                        label={PROGRESS_LABEL}
                        showValue
                        isSkeleton={isSkeleton}

                    />
                ),
                () => (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={isSkeleton}

                        text={statsLine(stats)}

                    />
                ),
            ]}
        />
    )

    return (
        <StackV
            gap={6}
            principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            isSkeleton={isSkeleton}

            items={[
                () => heroSection,
                () => (
                    <SurfaceCard
                        label={keepGoingLabel(milestoneLabel)}
                        isSkeleton={isSkeleton}


                        body={() => (
                            <Grid
                                columns={{ base: 1, sm: 2 }}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."

                                items={tasks.map((task) => ({
                                    key: task.id,
                                    content: () => (
                                        <ContinueCardItem
                                            title={`${task.sortIndex}. ${task.title}`}
                                            subtitle={TASK_SUBTITLE[task.subtitleState]}
                                            isSkeleton={isSkeleton}
                                            onPress={() => onSelectTask(task.id)}


                                        />
                                    ),
                                }))}
                            />
                        )}
                    />
                ),
            ]}
        />
    )
}

/**
 * The capstone landing overview. See the file header for the full contract.
 *
 * @param props - {@link PersonalProjectDashboardProps}
 */
const PersonalProjectDashboard = ({
    breadcrumbItems,
    title,
    description,
    githubStatus,
    currentTask,
    onContinue,
    milestoneLabel,
    tasks,
    onSelectTask,
    stats,
    isLoading = false,
    isEmpty = false,
    isSkeleton = false,
}: PersonalProjectDashboardProps) => {
    const crumbs: Array<BreadcrumbItem> = (breadcrumbItems ?? []).map((crumb) => ({
        key: crumb.key,
        label: crumb.label,
        onPress: crumb.onPress,
    }))

    const header = (
        <PageHeader

            isSkeleton={isSkeleton}
            breadcrumb={() =>
                isSkeleton || crumbs.length ? (
                    <div className="w-fit">
                        <Breadcrumbs collapseOnMobile items={crumbs} isSkeleton={isSkeleton} />
                    </div>
                ) : undefined
            }
            title={title}
            description={description}
            meta={() =>
                isSkeleton ? (
                    <Chip isSkeleton />
                ) : (
                    <Chip
                        tone={githubStatus.isConnected ? "success" : "default"}
                        icon={GithubLogoIcon}
                        text={githubStatus.label}
                    />
                )
            }
        />
    )

    const asyncBody = (
        <AsyncContent
            isLoading={isLoading}
            skeleton={() => (
                <Body
                    currentTask={{ sortIndex: 1, title: "" }}
                    onContinue={onContinue}
                    milestoneLabel={milestoneLabel}
                    tasks={SKELETON_TASKS}
                    onSelectTask={onSelectTask}
                    stats={{ done: 0, total: 0, attempts: 0, avgLabel: "" }}
                    isSkeleton

                />
            )}
            isEmpty={isEmpty}
            emptyContent={EMPTY_STATE}
            content={() => (
                <Body
                    currentTask={currentTask}
                    onContinue={onContinue}
                    milestoneLabel={milestoneLabel}
                    tasks={tasks}
                    onSelectTask={onSelectTask}
                    stats={stats}
                    isSkeleton={false}

                />
            )}
        />
    )

    return (
        <div>
            <StackV
                gap={6}
                isSkeleton={isSkeleton}

                items={[
                    () => header,
                    () => asyncBody,
                ]}
            />
        </div>
    )
}

export { PersonalProjectDashboard }

import { Skeleton as HeroSkeleton } from "@heroui/react"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { MessageRow } from "./MessageRow"
import {
    type QaMessageBubbleAnswer,
    type QaMessageBubbleProps,
} from "./types"

export type {
    QaMessageBubbleAuthor,
    QaMessageBubbleAnswer,
    QaMessageBubbleProps,
} from "./types"

/**
 * BLOCK — `QaMessageBubble`: one answer (plus its flattened replies) in a Q&A
 * conversation — author line, chat bubble body, an accept toggle (asker
 * only, top-level only), a reaction bar, and every reply beneath it,
 * read-only (see the component's own file header for why).
 */

/**
 * One answer (plus its flattened replies) in a `QaQuestionThread` conversation.
 *
 * @param props - {@link QaMessageBubbleProps}
 */
const QaMessageBubble = ({
    answer,
    currentUserId,
    canAccept,
    onAcceptAnswer,
    onReact,
    isSkeleton = false,
}: QaMessageBubbleProps) => {
    if (isSkeleton) {
        return (
            <div className="max-w-[92%]">
                <StackV
                    gap={2}
                    isSkeleton={isSkeleton}
                    items={[
                        () => (
                            <StackH
                                gap={2}
                                principle="separator-dot"
                                explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                                align="center"
                                items={[
                                    () => (
                                        <StackH
                                            gap={2}
                                            principle="icon-text"
                                            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                            align="center"
                                            items={[
                                                () => <Avatar isSkeleton size="sm" />,
                                                () => <HeroSkeleton className="h-3 w-16 rounded" />,
                                            ]}
                                        />
                                    ),
                                    () => <HeroSkeleton className="h-3 w-10 rounded" />,
                                ]}
                            />
                        ),
                        () => <HeroSkeleton className="h-16 w-full rounded-2xl" />,
                    ]}
                />
            </div>
        )
    }
    // `answer` is REQUIRED whenever `isSkeleton` is false (the discriminated union
    // above, already guaranteed by the early return) — `!` only satisfies narrowing
    // across the destructure, it never actually fires.
    const realAnswer = answer!

    return (
        <div>
            <StackV
                gap={2}
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <MessageRow
                            answer={realAnswer}
                            currentUserId={currentUserId}

                            interactive={{ canAccept, onAcceptAnswer, onReact }}
                        />
                    ),
                    ...(realAnswer.replies ?? []).map((reply: QaMessageBubbleAnswer) => () => (
                        <div key={reply.id} className="pl-8">
                            <MessageRow answer={reply} currentUserId={currentUserId} interactive={null} />
                        </div>
                    )),
                ]}
            />
        </div>
    )
}

