import React, { useMemo, useState } from "react"
import { cn } from "@heroui/react"
import { PushPinIcon, SealCheckIcon } from "@phosphor-icons/react"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { CourseQaComposer } from "@sb-components/starci/blocks/learn/CourseQaComposer/CourseQaComposer"
import { QaConversationHeader } from "@sb-components/starci/blocks/learn/QaConversationHeader/QaConversationHeader"
import { QaChatBubble } from "@sb-components/starci/blocks/learn/QaChatBubble/QaChatBubble"
import { QaReactionBar } from "@sb-components/starci/blocks/learn/QaReactionBar/QaReactionBar"
import { QaMessageBubble } from "@sb-components/starci/blocks/learn/QaMessageBubble/QaMessageBubble"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import type { ComponentTypeWithSkeleton , SkeletonProps } from "@sb-components/frames/_slot"

/**
 * BLOCK — `QaQuestionThread`: ONE course-Q&A conversation — a collapsed social
 * inbox row that presses open into the full conversation (header, question
 * bubble, every answer, a bottom composer). See the component file header for
 * the full contract, the local-state judgement call, and the assumed-contract
 * risk on the four sibling blocks that did not exist yet when this was written.
 */

/** Reaction kinds a message in this thread can carry (mirrors backend `ReactionType`). */
export type QaReactionType = "like" | "love" | "haha" | "wow" | "sad" | "angry"

/** Minimal identity carried by whoever wrote the question or an answer. */
export interface QaQuestionThreadAuthor {
    /** Stable id — drives "is this the viewer's own message" checks. */
    id: string
    /** Display name, already resolved by the caller (falls back to username upstream). */
    displayName: string
    /** Avatar image url. Omitted → `Avatar`'s own generated/initials fallback chain. */
    avatarUrl?: string
}

/** Where a question was asked — drives the scope chip's own wording (§14d.1). */
export type QaQuestionThreadScope =
    | { kind: "lesson", lessonTitle: string }
    | { kind: "general" }

/** One answer — or, once flattened, one reply-to-a-reply — in the conversation. */
export interface QaThreadAnswer {
    /** Stable id — the React key, and what accept/react actions target. */
    id: string
    /** Answer body, as authored markdown. */
    body: string
    /** Who wrote this answer. */
    author: QaQuestionThreadAuthor
    /** Already-formatted relative time, e.g. "2 hours ago" — no i18n layer at this tier. */
    createdTimeAgo: string
    /** `true` → this is the asker's chosen answer; only ever true on a DIRECT (top-level) answer. */
    isAcceptedAnswer?: boolean
    /** Total reactions on this answer. */
    reactionCount: number
    /** The viewer's own reaction on this answer, or null. */
    myReaction: QaReactionType | null
    /** Already-loaded flattened replies to THIS answer — rendered as sibling bubbles, not indented. */
    replies?: ReadonlyArray<QaThreadAnswer>
}

/** The question this whole thread is about. */
export interface QaQuestionThreadQuestion {
    /** Question primary id. */
    id: string
    /** Who asked it. */
    author: QaQuestionThreadAuthor
    /** Already-formatted relative time, e.g. "2 hours ago". */
    createdTimeAgo: string
    /** `true` → a pin glyph rides beside the asker's name (founder moderation). */
    isPinned?: boolean
    /** `true` → the asker is the founder (drives the founder-author badge). */
    isFounderAuthor?: boolean
    /** Question body, as authored markdown. */
    body: string
    /** Which lesson (or "course-wide") this question belongs to. */
    scope: QaQuestionThreadScope
    /** Total answers (top-level + replies) — the SSOT count, independent of how many `answers` are loaded below. */
    replyCount: number
    /** `true` → at least one answer came from the course founder. */
    answeredByFounder?: boolean
    /** Total reactions on the question itself (the question is a comment too). */
    reactionCount: number
    /** The viewer's own reaction on the question, or null. */
    myReaction: QaReactionType | null
    /** Already-loaded top-level answers — this design-system block does no fetching (§13). */
    answers: ReadonlyArray<QaThreadAnswer>
}

/** The signed-in viewer's identity — pass-through shape, matches `src`'s real `QuestionRow` contract 1:1. */
export interface QaQuestionThreadViewer {
    username: string
    avatar?: string
}

/** Props for {@link QaQuestionThread}. */
export interface QaQuestionThreadProps {
    /** The question to render. */
    question: QaQuestionThreadQuestion
    /** Current viewer id — drives own-bubble alignment + accept-answer eligibility; null when unknown. */
    currentUserId: string | null
    /** Current viewer identity for the bottom composer's avatar; null when signed out. */
    currentUser: QaQuestionThreadViewer | null
    /** Called after a new answer is posted — bumps the parent roll-up's aggregates. */
    onAnswered?: () => void
    /**
     * `true` → the collapsed row draws its own shimmer mirror and stops accepting
     * presses (there is no real conversation to open yet). See the file header
     * for why this never reaches `SurfaceCard.Pressable`'s own generic flag.
     */
    isSkeleton?: boolean
}

/** The block's own scope → label vocabulary (§14d.1) — never handed in pre-formatted. */
const scopeLabel = (scope: QaQuestionThreadScope): string =>
    scope.kind === "lesson" ? `Lesson: ${scope.lessonTitle}` : "General"

/** The block's own status → label vocabulary (§14d.1). */
const statusLabel = (replyCount: number, answeredByFounder?: boolean): string => {
    if (replyCount <= 0) {
        return "Unanswered"
    }
    return answeredByFounder ? "Instructor answered" : "Answered"
}

/** Options controlling which chips {@link buildQuestionChips} builds. */
interface QaQuestionChipsOptions {
    /** `true` → both chips draw their shimmer mirror. */
    isSkeleton: boolean
    /**
     * `true` → a third, quiet reply-count fact rides beside the two chips. The
     * collapsed row needs it (no `QaConversationHeader` around to say it
     * elsewhere); the expanded question bubble does not, since the header above
     * it already carries the same count.
     */
    includeReplyCount: boolean
}

/**
 * The scope + status chip pair shared by the collapsed row and the expanded
 * question bubble — built ONCE so the two never drift on wording.
 */
const buildQuestionChips = (question: QaQuestionThreadQuestion, options: QaQuestionChipsOptions): Array<ComponentTypeWithSkeleton> => {
    const { isSkeleton, includeReplyCount } = options

    if (isSkeleton) {
        return [
            () => <Chip isSkeleton />,
            () => <Chip isSkeleton />,
        ]
    }

    const items: Array<ComponentTypeWithSkeleton> = [
        () => <Chip tone="default" text={scopeLabel(question.scope)} />,
        () => (
            <Chip
                tone={question.replyCount > 0 ? "success" : "default"}
                text={statusLabel(question.replyCount, question.answeredByFounder)}

            />
        ),
    ]

    if (includeReplyCount && question.replyCount > 0) {
        items.push(() => (
            <Typography
                size="xs"
                color="muted"
                text={`${question.replyCount} replies`}

            />
        ))
    }

    return items
}

/** Apply (or clear) a reaction pick against a `{count, myReaction}` pair, adjusting the count by exactly one. */
const applyReaction = (
    count: number,
    current: QaReactionType | null,
    next: QaReactionType | null,
): { count: number, myReaction: QaReactionType | null } => {
    if (current === next) {
        return { count, myReaction: current }
    }
    const delta = (next != null ? 1 : 0) - (current != null ? 1 : 0)
    return { count: Math.max(0, count + delta), myReaction: next }
}

/**
 * One course-Q&A conversation. See the file header for the full contract, the
 * assumed-sibling-contract risk, and the local-state judgement call.
 *
 * @param props - {@link QaQuestionThreadProps}
 */
const QaQuestionThread = ({
    question,
    currentUserId,
    currentUser,
    onAnswered,
    isSkeleton = false,
}: QaQuestionThreadProps) => {
    // Collapsed ⇄ Expanded is a real TOGGLE local to this instance, exactly like
    // `src`'s own `QuestionRow` (see file header) — never lifted to a prop.
    const [isExpanded, setIsExpanded] = useState(false)

    // Seeded ONCE from props — correct because this block is instantiated once per
    // question (`key={question.id}` at the call site remounts it on real data
    // change), same assumption `src`'s `QuestionRow` makes for its own local state.
    const [answers, setAnswers] = useState<ReadonlyArray<QaThreadAnswer>>(question.answers)
    const [questionReaction, setQuestionReaction] = useState({ count: question.reactionCount, myReaction: question.myReaction })
    const [draft, setDraft] = useState("")

    const isMineQuestion = currentUserId != null && currentUserId === question.author.id
    const askerDisplayName = isMineQuestion ? "You" : question.author.displayName

    // Distinct answerers → the "who joined in" avatar group in the header.
    const participants = useMemo<Array<QaQuestionThreadAuthor>>(() => {
        const seen = new Set<string>()
        const list: Array<QaQuestionThreadAuthor> = []
        for (const answer of answers) {
            if (!seen.has(answer.author.id)) {
                seen.add(answer.author.id)
                list.push(answer.author)
            }
        }
        return list
    }, [answers])

    const onReactQuestion = (type: QaReactionType | null) => {
        setQuestionReaction((prev) => applyReaction(prev.count, prev.myReaction, type))
    }

    const onReactAnswer = (answerId: string, type: QaReactionType | null) => {
        setAnswers((prev) => prev.map((answer) => {
            if (answer.id !== answerId) {
                return answer
            }
            const { count, myReaction } = applyReaction(answer.reactionCount, answer.myReaction, type)
            return { ...answer, reactionCount: count, myReaction }
        }))
    }

    const onAcceptAnswer = (answerId: string, accepted: boolean) => {
        setAnswers((prev) => prev.map((answer) => (answer.id === answerId ? { ...answer, isAcceptedAnswer: accepted } : answer)))
    }

    const canSubmitAnswer = draft.trim().length > 0 && currentUserId != null && currentUser != null

    const onSubmitAnswer = () => {
        if (!canSubmitAnswer || currentUserId == null || currentUser == null) {
            return
        }
        const newAnswer: QaThreadAnswer = {
            id: `local-${answers.length}-${Date.now()}`,
            body: draft.trim(),
            author: { id: currentUserId, displayName: currentUser.username, avatarUrl: currentUser.avatar },
            createdTimeAgo: "Just now",
            reactionCount: 0,
            myReaction: null,
        }
        setAnswers((prev) => [...prev, newAnswer])
        setDraft("")
        onAnswered?.()
    }

    // ── LEAF — Collapsed: a private social inbox row, the whole row pressable ──
    if (!isExpanded) {
        const askerNameRow = (
            <StackH
                gap={3}
                principle="identity"
                explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                at="sm"
                align="center"
                isSkeleton={isSkeleton}

                items={[
                    () =>
                        isSkeleton ? (
                            <Typography size="xs" weight="medium" isSkeleton />
                        ) : (
                            <>
                                {question.isPinned ? (
                                    <PushPinIcon weight="fill" aria-hidden focusable="false" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                                ) : null}
                                <Typography size="xs" weight="medium" text={askerDisplayName} />
                                {question.isFounderAuthor ? (
                                    <SealCheckIcon weight="fill" aria-hidden focusable="false" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                                ) : null}
                                <Typography size="xs" color="muted" text={`· ${question.createdTimeAgo}`} />
                            </>
                        ),
                ]}
            />
        )

        const questionPreview = isSkeleton ? (
            <StackV
                gap={2}
                isSkeleton={isSkeleton}

                items={[
                    () => <Typography size="sm" isSkeleton />,
                    () => <Typography size="sm" isSkeleton />,
                ]}
            />
        ) : (
            <div className="[&_p]:m-0 [&_p]:line-clamp-2">
                <MarkdownContent
                    source={question.body}
                    measure="compact"

                />
            </div>
        )

        const previewColumn = (
            <StackV
                gap={2}
                classNames={["min-w-0", "flex-1"]}
                isSkeleton={isSkeleton}

                items={[
                    () => askerNameRow,
                    () => questionPreview,
                    () => (
                        <Cluster
                            gap={3}
                            items={buildQuestionChips(question, { isSkeleton, includeReplyCount: true })}

                        />
                    ),
                ]}
            />
        )

        const collapsedRow = (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="start"
                isSkeleton={isSkeleton}

                items={[
                    () => (
                        <div>
                            <Avatar
                                src={question.author.avatarUrl}
                                name={question.author.displayName}
                                seed={question.author.id}
                                size="sm"
                                isSkeleton={isSkeleton}

                            />
                        </div>
                    ),
                    () => previewColumn,
                    ...(!isSkeleton ? [() => (
                        <span
                            aria-hidden
                            className={cn("size-2 shrink-0 rounded-full", question.replyCount > 0 ? "bg-success" : "bg-warning")}
                        />
                    )] : []),
                ]}
            />
        )

        return (
            <div>
                <div>
                    <SurfaceCard
                        onPress={() => setIsExpanded(true)}
                        isDisabled={isSkeleton}

                        body={() => collapsedRow}
                    />
                </div>
            </div>
        )
    }

    // ── LEAF — Expanded: the full conversation ─────────────────────────────────
    const questionMetaRow = (
        <StackH
            gap={3}
            principle="identity"
            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
            at="sm"
            align="center"
            isSkeleton={isSkeleton}

            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="xs" weight="medium" isSkeleton={isSkeleton} text={askerDisplayName} />,
                ...(question.isFounderAuthor ? [() => (
                    <SealCheckIcon weight="fill" aria-hidden focusable="false" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                )] : []),
                ...(question.isPinned ? [() => (
                    <PushPinIcon weight="fill" aria-hidden focusable="false" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                )] : []),
                ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={question.createdTimeAgo} />,
            ]}
        />
    )

    const questionFooterRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            at="sm"
            align="center"
            isSkeleton={isSkeleton}

            items={[
                () => (
                    <Cluster
                        gap={3}
                        items={buildQuestionChips(question, { isSkeleton: false, includeReplyCount: false })}

                    />
                ),
                ({ isSkeleton }: SkeletonProps) => (
                    <QaReactionBar
                        count={questionReaction.count}
                        myReaction={questionReaction.myReaction}
                        onReact={onReactQuestion}
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    // the question itself, as the first bubble of the conversation
    const questionBubble = (
        <div className={cn("flex w-full", isMineQuestion ? "justify-end" : "justify-start")}>
            <div className="max-w-[92%]">
                <StackV
                    gap={2}
                    principle="title-subtitle"
                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                    align={isMineQuestion ? "end" : "stretch"}
                    classNames={["min-w-0"]}
                    isSkeleton={isSkeleton}

                    items={[
                        () => questionMetaRow,
                        ({ isSkeleton }: SkeletonProps) => (
                            <QaChatBubble role={isMineQuestion ? "user" : "assistant"} isSkeleton={isSkeleton}>
                                <div className="[&_p]:m-0">
                                    <MarkdownContent
                                        source={question.body}
                                        measure="compact"

                                    />
                                </div>
                            </QaChatBubble>
                        ),
                        () => questionFooterRow,
                    ]}
                />
            </div>
        </div>
    )

    // answers — QaMessageBubble recurses internally for flattened reply-to-reply
    const answerRows = answers.length === 0 ? (
        <Typography
            size="sm"
            color="muted"
            text="No answers yet — be the first."

        />
    ) : (
        answers.map((answer) => (
            <QaMessageBubble
                key={answer.id}
                answer={answer}
                currentUserId={currentUserId}
                canAccept={isMineQuestion}
                onAcceptAnswer={(accepted: boolean) => onAcceptAnswer(answer.id, accepted)}
                onReact={(type: QaReactionType | null) => onReactAnswer(answer.id, type)}

            />
        ))
    )

    const conversationBody = (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}

            items={[
                () => questionBubble,
                () => answerRows,
            ]}
        />
    )

    const threadPanel = (
        <StackV
            gap={6}
            isSkeleton={isSkeleton}

            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <QaConversationHeader
                        asker={{
                            id: question.author.id,
                            displayName: question.author.displayName,
                            avatarUrl: question.author.avatarUrl,
                        }}
                        isFounderAsker={question.isFounderAuthor}
                        participants={participants}
                        replyCount={question.replyCount}
                        onCollapse={() => setIsExpanded(false)}
                        isSkeleton={isSkeleton}

                    />
                ),
                () => conversationBody,
                // bottom composer — the only way to answer a course-general question
                ({ isSkeleton }: SkeletonProps) => (
                    <CourseQaComposer
                        mode="plain"
                        currentUser={currentUser ? { name: currentUser.username, avatarSrc: currentUser.avatar } : undefined}
                        value={draft}
                        onValueChange={setDraft}
                        onSubmit={onSubmitAnswer}
                        placeholder="Write your answer…"
                        submitLabel="Send"
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    return (
        <div>
            <SurfaceCard body={() => threadPanel} />
        </div>
    )
}

export { QaQuestionThread }

import React from "react"
import type { ReactNode } from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { RatingBar, type RatingOption } from "@sb-components/starci/blocks/learn/RatingBar/RatingBar"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `QuizRecapList` — the run is over: go back over what you answered and say how well
 * you actually knew each one. This learner-supplied grade is not the run's verdict —
 * a card can be marked correct yet be one the learner wants back tomorrow (the
 * `CorrectButShaky` case), which the spaced-repetition schedule needs. Already-graded
 * cards keep their rating bar — nothing locks after a tap, so a changed mind still
 * counts. Card count and which are rated are states of one shape; finishing changes
 * only the counter line.
 */

/** One answered card in the recap. */
export interface QuizRecapCard {
    /** Stable React key. */
    key: string
    /** The question, as authored markdown. */
    question: string
    /** The expected answer, as authored markdown. */
    expectedAnswer: string
    /** What the learner typed during the run. */
    givenAnswer?: string
    /** How the run judged it. */
    wasCorrect: boolean
    /** The learner's own recall grade, once they have given one. */
    rating?: number
}

interface QuizRecapListOwnProps {
    /** Recall grades offered per card. */
    ratingOptions: Array<RatingOption>
    /** Fired with the card key and the grade the learner picked. */
    onRate: (cardKey: string, grade: number) => void
    /** Accessible name for each card's rating group, localized by the caller. */
    ratingAriaLabel: string
    /** Card count to shimmer while `isSkeleton` (no real `cards` yet). Defaults to `3`. */
    skeletonCount?: number
}

/**
 * Props for {@link QuizRecapList}. `cards` is REQUIRED unless `isSkeleton`
 * (§12b) — a shimmer recap has no real cards to show yet.
 */
export type QuizRecapListProps = QuizRecapListOwnProps &
    (
        | { isSkeleton: true; cards?: Array<QuizRecapCard> }
        | { isSkeleton?: false; cards: Array<QuizRecapCard> }
    )

/**
 * One recap card's content — verdict chip, question, given/expected answers,
 * rating bar. Extracted to a helper (rather than hoisted to a const) because
 * it depends on the loop variable `card` from the `.map()` that calls it.
 */
const recapCardBody = (
    card: QuizRecapCard,
    ratingOptions: Array<RatingOption>,
    onRate: (cardKey: string, grade: number) => void,
    ratingAriaLabel: string,
): ReactNode => (
    <StackV
        gap={6}
        principle="block-boundary"
        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
        items={[
            () => (
                <StackH
                    gap={3}
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    align="center"

                    items={[
                        () => (
                            <Chip
                                tone={card.wasCorrect ? "success" : "danger"}
                                text={card.wasCorrect ? "Correct" : "Incorrect"}

                            />
                        ),
                    ]}
                />
            ),
            () => (
                <MarkdownContent
                    source={card.question}
                    measure="compact"

                />
            ),
            ...(card.givenAnswer != null ? [() => (
                <StackV
                    gap={3}

                    items={[
                        () => <Typography size="xs" color="muted" text="Your answer" />,
                        () => <Typography size="sm" text={card.givenAnswer} />,
                    ]}
                />
            )] : []),
            () => (
                <StackV
                    gap={3}

                    items={[
                        () => <Typography size="xs" color="muted" text="Expected answer" />,
                        () => (
                            <MarkdownContent
                                source={card.expectedAnswer}
                                measure="compact"

                            />
                        ),
                    ]}
                />
            ),
            // Stays put after a tap. A learner going back over a run changes
            // their mind, and removing the control would make the first tap
            // final without ever saying so.
            () => (
                <RatingBar
                    options={ratingOptions}
                    onRate={(grade) => onRate(card.key, grade)}
                    ariaLabel={ratingAriaLabel}


                />
            ),
        ]}
    />
)

/**
 * The end-of-run recap. See the file header for the full contract.
 *
 * @param props - {@link QuizRecapListProps}
 */
const QuizRecapList = ({
    cards,
    ratingOptions,
    onRate,
    ratingAriaLabel,
    isSkeleton = false,
    skeletonCount = 3,
}: QuizRecapListProps) => {
    if (isSkeleton) {
        return (
            <div>
                <StackV
                    gap={6}
                    isSkeleton={isSkeleton}
                    items={[
                        () => <HeroSkeleton className="h-3.5 w-40 rounded" />,
                        ...Array.from({ length: skeletonCount }, (_unused, index) => () => (
                            <SurfaceCard
                                key={index}

                                body={() => (
                                    <StackV
                                        gap={6}
                                        isSkeleton={isSkeleton}
                                        items={[
                                            () => <HeroSkeleton className="h-5 w-16 rounded-full" />,
                                            () => <HeroSkeleton className="h-4 w-full rounded" />,
                                            () => <HeroSkeleton className="h-4 w-2/3 rounded" />,
                                        ]}
                                    />
                                )}
                            />
                        )),
                    ]}
                />
            </div>
        )
    }
    const unrated = (cards ?? []).filter((card) => card.rating == null).length

    return (
        <div>
            <StackV
                gap={6}
                isSkeleton={isSkeleton}
                items={[
                    // Counted, not celebrated. The recap is work; the learner is here to finish
                    // it, not to be congratulated for starting it.
                    () => (
                        <Typography
                            size="sm"
                            color="muted"
                            text={unrated > 0 ? `${unrated}/${(cards ?? []).length} cards left to self-grade` : `All ${(cards ?? []).length} cards self-graded`}

                        />
                    ),
                    ...(cards ?? []).map((card) => () => (
                        <SurfaceCard
                            key={card.key}

                            body={() => recapCardBody(card, ratingOptions, onRate, ratingAriaLabel)}
                        />
                    )),
                ]}
            />
        </div>
    )
}

export { QuizRecapList }

import React from "react"
import type { ComponentType, ReactNode, SVGProps } from "react"
import { InfoIcon, LightbulbIcon, MapPinIcon, WarningCircleIcon } from "@phosphor-icons/react"
import { cn } from "@heroui/react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import {
    AsyncContentEmpty,
    AsyncContentError,
} from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCardAccordion, type SurfaceCardAccordionItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `SubmissionFindingsList` — "Feedback": one accordion row per quality-gate finding
 * on a graded attempt — severity icon + plain-text message (backtick code only) +
 * location chip in the trigger; markdown detail, a linked file location, and a
 * markdown suggestion in the panel. The frame is `SurfaceCard.Accordion` end to end;
 * the block supplies the domain (severity → icon/tone/sort-rank, the high→low sort,
 * the repo-URL → file-link builder). Loading, empty, error, and populated are all
 * states of the one accordion card, routed through its own `isSkeleton`/`emptyState`
 * axes.
 */

/** Severity a finding carries — drives the trigger icon/tone and the sort rank (high sorts first). */
export type SubmissionFeedbackSeverity = "high" | "medium" | "low"

/** An icon passed as a COMPONENT, rendered by this block at the size the text beside it uses. */
type SeverityIconComponent = ComponentType<SVGProps<SVGSVGElement> & { weight?: "regular" | "bold" }>

/** One severity's trigger icon + text tone + sort rank — see {@link SEVERITY_VISUAL}. */
interface SeverityVisual {
    /** Trigger icon for this severity. */
    icon: SeverityIconComponent
    /** Tailwind text-color class for the icon (matches the severity's weight). */
    toneClassName: string
    /** Sort rank — lower sorts first (high = 0). */
    rank: number
}

/**
 * Severity → trigger icon + text tone + sort rank. This is the block's own
 * domain vocabulary, never something a caller hands in.
 */
const SEVERITY_VISUAL: Record<SubmissionFeedbackSeverity, SeverityVisual> = {
    high: { icon: WarningCircleIcon, toneClassName: "text-danger", rank: 0 },
    medium: { icon: WarningCircleIcon, toneClassName: "text-warning", rank: 1 },
    low: { icon: InfoIcon, toneClassName: "text-muted", rank: 2 },
}

/** One quality-gate finding for a graded attempt. */
export interface SubmissionFinding {
    /** Stable id — also the accordion row's expand key. */
    id: string
    /**
     * Short summary shown (clamped to one line) in the accordion trigger — plain
     * text, at most `` `code` `` spans (never bold/italic/link: a trigger title
     * is tier 1). Full markdown
     * belongs in `detail`/`suggestion`, which render in the panel body instead.
     */
    message: string
    /** Longer explanation, authored as markdown, shown in the panel. */
    detail?: string
    /** Suggested fix, authored as markdown, shown in the panel. */
    suggestion?: string
    /** Repo-relative file path this finding points at, e.g. `src/app/page.tsx`. */
    location?: string
    /** High/medium/low — decides the trigger icon/tone and the sort order. */
    severity: SubmissionFeedbackSeverity
    /** Author-authored order among findings that share a severity. Defaults to `0`. */
    sortIndex?: number
}

/** Props for {@link SubmissionFindingsList}. */
export interface SubmissionFindingsListProps {
    /** The findings, in ANY order — the block re-sorts them itself (severity, then `sortIndex`). */
    findings: Array<SubmissionFinding>
    /**
     * Repo URL the attempt was submitted from — turns each `location` into a
     * `blob/HEAD` deep-link. Omit → `location` still shows, as plain text.
     */
    repositoryUrl?: string
    /** Section label rendered above the card (e.g. `"Feedback"`). */
    label: string
    /** `true` → this list's own fetch is in flight; the card falls to its self-mirror. */
    isLoading?: boolean
    /** `true` (once loading has finished) → the card falls to its empty message. */
    isEmpty?: boolean
    /** Empty-state title. Defaults to a standard "no findings yet" line. */
    emptyLabel?: string
    /** Truthy → the card falls to its error message (beats loading/empty — see file header). */
    error?: unknown
    /** Retry handler — paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button — required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** `true` → a parent-forced skeleton paint, same branch as `isLoading` (see file header). */
    isSkeleton?: boolean
}

const EMPTY_LABEL_DEFAULT = "No feedback yet"
const ERROR_TITLE = "Could not load feedback"

/**
 * High → low, then by each finding's own authored order. The block's own
 * vocabulary, so a caller never has to pre-sort what it hands in.
 */
const sortFindings = (findings: ReadonlyArray<SubmissionFinding>): Array<SubmissionFinding> =>
    [...findings].sort((a, b) => {
        const rankDiff = SEVERITY_VISUAL[a.severity].rank - SEVERITY_VISUAL[b.severity].rank
        return rankDiff !== 0 ? rankDiff : (a.sortIndex ?? 0) - (b.sortIndex ?? 0)
    })

/**
 * `repositoryUrl` + a repo-relative `location` → a `blob/HEAD` deep-link. Ported
 * from `FindingAccordionItem` unchanged.
 */
const buildLocationHref = (location: string, repositoryUrl?: string): string | undefined =>
    repositoryUrl ? `${repositoryUrl.replace(/\.git$/, "")}/blob/HEAD/${location.replace(/^\//, "")}` : undefined

/**
 * Trigger icon: the severity glyph, its OWN tone colour independent of the
 * title text — rides `titleStart`, not composed into `title` itself (§ same
 * rule as `ChallengeDeliverableList`'s status icon).
 */
const findingIcon = (finding: SubmissionFinding): ReactNode => {
    const { icon: Icon, toneClassName } = SEVERITY_VISUAL[finding.severity]
    return (
        <Icon
            aria-hidden
            focusable="false"
            weight="bold"

            className={cn("size-3.5 shrink-0", toneClassName)}
        />
    )
}

/** Trailing trigger slot: the finding's file location, as a quiet chip. */
const findingLocationChip = (finding: SubmissionFinding): ReactNode | undefined =>
    finding.location ? (
        <Chip
            tone="default"
            text={finding.location}


        />
    ) : undefined

/**
 * Panel content: the markdown detail, the linked file location, and the markdown
 * suggested fix — each optional, each its own row (`related`: independent facts
 * about one finding, not a single unit of meaning).
 */
const findingPanel = (finding: SubmissionFinding, repositoryUrl: string | undefined): ReactNode => {
    const locationHref = finding.location ? buildLocationHref(finding.location, repositoryUrl) : undefined
    const locationRow = finding.location ? (
        <StackH
            gap={2}
            align="center"
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            items={[
                () => <MapPinIcon aria-hidden focusable="false" weight="bold" className="size-3 shrink-0 text-muted" />,
                () =>
                    locationHref ? (
                        <Typography
                            size="xs"
                            color="muted"
                            isLink
                            underlineOnHover
                            href={locationHref}
                            target="_blank"
                            rel="noopener noreferrer"
                            text={finding.location}

                        />
                    ) : (
                        <Typography size="xs" color="muted" text={finding.location} />
                    ),
            ]}
        />
    ) : null
    const suggestionRow = finding.suggestion ? (
        <StackH
            gap={2}
            align="start"
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            items={[
                () => <LightbulbIcon aria-hidden focusable="false" weight="bold" className="size-3.5 shrink-0 text-muted" />,
                () => (
                    <div className="min-w-0 flex-1 text-muted [&_p]:m-0">
                        <MarkdownContent
                            source={finding.suggestion ?? ""}
                            measure="compact"

                        />
                    </div>
                ),
            ]}
        />
    ) : null
    return (
        <StackV
            gap={3}

            items={[
                ...(finding.detail ? [() => (
                    <div className="text-muted [&_p]:m-0">
                        <MarkdownContent
                            source={finding.detail ?? ""}
                            measure="compact"

                        />
                    </div>
                )] : []),
                () => locationRow,
                () => suggestionRow,
            ]}
        />
    )
}

interface FindingsErrorEmptyStateProps {
    onRetry?: () => void
    retryLabel?: string
}
const ErrorEmptyState = ({ onRetry, retryLabel }: FindingsErrorEmptyStateProps) => (
    <AsyncContentError
        title={ERROR_TITLE}
        onRetry={onRetry}
        retryLabel={retryLabel}
    />
)

interface FindingsPlainEmptyStateProps {
    title: string
}
const PlainEmptyState = ({ title }: FindingsPlainEmptyStateProps) => (
    <AsyncContentEmpty title={title} />
)

/**
 * The "Feedback" findings card. See the file header for what this block owns
 * (severity vocabulary, sort order, the repo-URL→file-link builder) and why
 * loading/empty/error all stay bounded inside the one `SurfaceCard.Accordion`
 * frame instead of swapping it out for `AsyncContent`'s own switch.
 *
 * @param props - {@link SubmissionFindingsListProps}
 */
const SubmissionFindingsList = ({
    findings,
    repositoryUrl,
    label,
    isLoading = false,
    isEmpty,
    emptyLabel,
    error,
    onRetry,
    retryLabel,
    isSkeleton = false,
}: SubmissionFindingsListProps) => {
    // Error outranks even a stale loading/skeleton flag — same priority order
    // `AsyncContent` itself documents ("error → loading → empty → content") — so a
    // caller handing both `error` and `isLoading` still sees the error, not a
    // skeleton pretending the fetch is still running.
    const skeleton = !error && (isLoading || isSkeleton)
    const resolvedEmpty = !error && (isEmpty ?? findings.length === 0)

    const items: Array<SurfaceCardAccordionItem> = error
        ? []
        : sortFindings(findings).map((finding) => ({
            id: finding.id,
            titleStart: () => findingIcon(finding),
            title: finding.message,
            titleEnd: () => findingLocationChip(finding),
            body: () => findingPanel(finding, repositoryUrl),
        }))

    const emptyState = error
        ? () => <ErrorEmptyState onRetry={onRetry} retryLabel={retryLabel} />
        : resolvedEmpty
            ? () => <PlainEmptyState title={emptyLabel ?? EMPTY_LABEL_DEFAULT} />
            : undefined

    return (
        <div>
            <SurfaceCardAccordion
                label={label}
                items={items}
                isSkeleton={skeleton}
                emptyState={emptyState}


            />
        </div>
    )
}

