import React, { useEffect, useMemo, useState } from "react"
import { CheckCircleIcon, SparkleIcon, XCircleIcon } from "@phosphor-icons/react"
import { DrawerShell } from "@sb-components/composites/layout/DrawerShell/DrawerShell"
import {
    AsyncContent,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { EnumChip } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { InlineIconLabel } from "@sb-components/composites/text/InlineIconLabel/InlineIconLabel"
import { MODEL_CATEGORY_MAP, type AiModelCategory } from "@sb-components/starci/blocks/learn/SubmissionScoreCard/SubmissionScoreCard"
import { Pagination } from "@sb-components/atoms/navigation/Pagination/Pagination"

/**
 * `SubmissionAttemptsDrawer` — a presentational overlay drawer listing every
 * past graded attempt at one challenge requirement, client-paginated. A row is
 * the select action: tapping it both picks that attempt and closes the drawer.
 * Pagination is owned inside this block (the full attempt list in, sliced
 * 6-at-a-time), not a caller-controlled `currentPage`/`totalPages` pair.
 */

/** One past graded attempt at this challenge requirement. */
export interface SubmissionAttemptRecord {
    /** Stable id — the value reported to {@link SubmissionAttemptsDrawerProps.onSelect}. */
    id: string
    /** 1-based order the attempt was made in — the row turns this into "Attempt N". */
    attemptNumber: number
    /** `null` → not graded yet; the row shows an "ungraded" chip instead of a number. */
    score: number | null
    /** Denominator for `score`. `null` → the score renders bare (no "/max"). */
    maxScore: number | null
    /** Drives the verdict icon + `Chip` tone once `score` is set — pass (`success`) or fail (`danger`). */
    isPassing: boolean
    /** Already-humanized relative time (e.g. "2 hours ago"). Absent → the byline row drops the time. */
    processedTimeAgo?: string
    /** The model that graded this attempt. Absent → the byline row does not draw at all (same rule `SubmissionScoreCard` uses). */
    gradedByModel?: string
    /** Cost/quality tier of {@link gradedByModel}. */
    modelCategory?: AiModelCategory
}

/** Props for {@link SubmissionAttemptsDrawer}. */
export interface SubmissionAttemptsDrawerProps {
    /** Whether the drawer is currently open. Forwarded to `DrawerShell`. */
    isOpen: boolean
    /** Open-state change handler (backdrop click, Escape, close button, or a row selection). Forwarded to `DrawerShell`. */
    onOpenChange: (open: boolean) => void
    /** The FULL attempt history (newest first) — this block paginates it client-side, same as real `src`. */
    attempts: Array<SubmissionAttemptRecord>
    /** The attempt currently being viewed — highlighted with a trailing check. */
    selectedAttemptId?: string
    /** Fired with an attempt id when the reader taps its row. The drawer closes itself right after (same gesture as real `src`). */
    onSelect: (attemptId: string) => void
    /** `true` → this list's own fetch is in flight; the drawer shows its skeleton mirror. */
    isLoading?: boolean
    /** `true` (once loading has finished) → the drawer falls to its empty message. */
    isEmpty?: boolean
    /** Truthy → the drawer falls to its error message (beats loading, per `AsyncContent`). */
    error?: unknown
    /** Retry handler — paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button — required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** Which edge the panel slides in from. Real `src` picks bottom-on-mobile itself; this port leaves that call to the caller. @default "right" */
    placement?: "top" | "bottom" | "left" | "right"
}

/** Fixed, block-owned title (§14d.1) — real `src` appends the live count, so this does too. */
const DRAWER_TITLE = "Submission history"
const EMPTY_TITLE = "No submissions yet"
const ERROR_TITLE = "Couldn't load the submission history"
const PAGER_ARIA_LABEL = "Submission history pagination"
const UNGRADED_LABEL = "Ungraded"

/** Attempts per page — same constant real `src` uses. */
const HISTORY_PAGE_SIZE = 6
/** How many skeleton rows mirror the list while `attempts` hasn't landed yet. */
const SKELETON_ATTEMPT_COUNT = 3

/** One attempt's verdict `Chip` shape — tone/icon/text, all derived from data. */
const scoreChipFor = (attempt: SubmissionAttemptRecord): { tone: "success" | "danger" | "default"; icon?: typeof CheckCircleIcon; text: string } => {
    if (attempt.score == null) {
        return { tone: "default", text: UNGRADED_LABEL }
    }
    return {
        tone: attempt.isPassing ? "success" : "danger",
        icon: attempt.isPassing ? CheckCircleIcon : XCircleIcon,
        text: attempt.maxScore != null ? `${attempt.score}/${attempt.maxScore}` : `${attempt.score}`,
    }
}

/** Turns one attempt into a {@link SurfaceCardListItem}'s free-form `content` — mirrors real `src`'s row exactly: attempt line + verdict chip + time-ago on line 1, model byline on line 2. */
const attemptRowContent = (attempt: SubmissionAttemptRecord, isSelected: boolean) => {
    const chip = scoreChipFor(attempt)

    const attemptLabelAndChip = [
        () => (
            <Typography
                text={`Attempt ${attempt.attemptNumber}`}
                size="sm"
                weight="medium"

            />
        ),
        () => <Chip tone={chip.tone} icon={chip.icon} text={chip.text} />,
    ]

    // justify="between" pushes the timeago to the far edge — the PARENT does the
    // pushing, not a child margin; the label+chip stay grouped in their own inner track
    // so `between` only ever splits two things, not three.
    const attemptLineContent = [
        () => <StackH gap={3} align="center" principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            items={attemptLabelAndChip} />,
        ...(attempt.processedTimeAgo != null ? [() => (
            <Typography
                text={attempt.processedTimeAgo}
                size="xs"
                color="muted"

            />
        )] : []),
    ]

    const bylineContent = [
        () => (
            <InlineIconLabel
                icon={SparkleIcon}
                tone="default"
                size="xs"
                label={`Graded by ${attempt.gradedByModel}`}
            />
        ),
        ...(attempt.modelCategory != null ? [() => (
            <EnumChip
                value={attempt.modelCategory ?? ""}
                map={MODEL_CATEGORY_MAP}

            />
        )] : []),
    ]

    const rowContent = [
        () => (
            <StackH
                gap={3}
                align="center"
                justify="between"
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={attemptLineContent}
            />
        ),
        ...(attempt.gradedByModel != null ? [() => (
            <StackH gap={3} align="center" at="sm" principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                items={bylineContent}  />
        )] : []),
    ]

    // highlight-exception: the selected row's tint is baked into the row's own
    // content wrapper (a plain, un-tightened `<div>`), since `SurfaceCardListItem`
    // no longer takes a raw `className` — same class real `src`'s
    // `SurfaceListCardItem` uses.
    return (
        <div className={isSelected ? "bg-accent-soft hover:bg-accent-soft" : undefined}>
            <StackV gap={2} items={rowContent} />
        </div>
    )
}

/**
 * The attempts-history drawer. See the file header for the real-`src` rebuild
 * and why selecting a row closes the drawer in the same gesture.
 *
 * @param props - {@link SubmissionAttemptsDrawerProps}
 */
const SubmissionAttemptsDrawer = ({
    isOpen,
    onOpenChange,
    attempts,
    selectedAttemptId,
    onSelect,
    isLoading = false,
    isEmpty = false,
    error,
    onRetry,
    retryLabel,
    placement = "right",
}: SubmissionAttemptsDrawerProps) => {
    const [page, setPage] = useState(1)

    // reset to the first page whenever the drawer opens — same as real `src`.
    useEffect(() => {
        if (isOpen) {
            setPage(1)
        }
    }, [isOpen])

    const totalPages = Math.max(1, Math.ceil(attempts.length / HISTORY_PAGE_SIZE))
    const pagedAttempts = useMemo(
        () => attempts.slice((page - 1) * HISTORY_PAGE_SIZE, page * HISTORY_PAGE_SIZE),
        [attempts, page],
    )

    const emptyContent: AsyncContentEmptyProps = {
        title: EMPTY_TITLE,

    }

    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,
        onRetry,
        retryLabel,

    }

    const skeletonRows = Array.from({ length: SKELETON_ATTEMPT_COUNT }, () => () => (
        <div className="h-16 w-full rounded-2xl bg-default/40" />
    ))

    // `selected` (a trailing check) is only wired for the FIXED title/subtitle row
    // shape — this row uses free-form `content` instead (2 lines, richer than that
    // shape fits), so the highlight is baked into `attemptRowContent`'s own wrapper
    // div, same class real `src`'s `SurfaceListCardItem` uses.
    const items: Array<SurfaceCardListItem> = pagedAttempts.map((attempt) => ({
        key: attempt.id,
        content: () => attemptRowContent(attempt, attempt.id === selectedAttemptId),
        onPress: () => {
            onSelect(attempt.id)
            onOpenChange(false)
        },
    }))

    const listAndPager = [
        () => (
            <SurfaceCardList
                items={items}


            />
        ),
        ...(totalPages > 1 ? [() => (
            // `Pagination` hard-codes its own internal `aria-label` (§4) — the
            // wrapping `<nav>` is how this block's own accessible name still
            // gets attached, same convention `CourseQaQuestionList` uses.
            <nav aria-label={PAGER_ARIA_LABEL}>
                <Pagination
                    currentPage={page}
                    totalPages={totalPages}
                    onPageChange={setPage}

                />
            </nav>
        )] : []),
    ]

    return (
        <div>
            <DrawerShell
                isOpen={isOpen}
                onOpenChange={onOpenChange}
                placement={placement}
                title={`${DRAWER_TITLE} · ${attempts.length}`}
                body={() => (
                    <AsyncContent
                        isLoading={isLoading}
                        skeleton={() => (
                            <StackV
                                gap={3}

                                items={skeletonRows}
                            />
                        )}
                        isEmpty={isEmpty}
                        emptyContent={emptyContent}
                        error={error}
                        errorContent={errorContent}

                        content={() => (
                            <StackV
                                gap={4}


                                items={listAndPager}
                            />
                        )}
                    />
                )}
            />
        </div>
    )
}

export { SubmissionAttemptsDrawer }

import React from "react"
import { ModalShell } from "@sb-components/composites/layout/ModalShell/ModalShell"
import { Tabs, type TabItem } from "@sb-components/atoms/navigation/Tabs/Tabs"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { LinkSeeMore } from "@sb-components/atoms/navigation/Link/Link"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { AiQuotaLane, type AiQuotaLaneData } from "@sb-components/starci/blocks/ai/AiQuotaLane/AiQuotaLane"
import { AiQuotaSubscriptionPanel } from "@sb-components/starci/blocks/ai/AiQuotaSubscriptionPanel/AiQuotaSubscriptionPanel"
import {
    AiQuotaHistoryPanel,
    type AiQuotaHistoryChartPoint,
    type AiQuotaHistoryChargeItem,
} from "@sb-components/starci/blocks/ai/AiQuotaHistoryPanel/AiQuotaHistoryPanel"

/**
 * `AiQuotaModal` — the root overlay for "how much AI have I used": dialog shell
 * + title/tier-chip header + 3-tab strip + the active tab's panel + "view full
 * usage" link. Opened via the app's global overlay store; this port takes plain
 * `isOpen`/`onOpenChange`/`activeTab` props. One leaf (`Default`): the wrapper
 * shape never changes — only which `ai`-group block fills the panel slot. `tier`
 * (the header chip) and each tab's `isLoading` are further states.
 */

/** Which paid AI plan the viewer is on. `null` = free plan, no badge shown. */
export type AiQuotaTier = "plus" | "pro" | "max" | null

/** The three tabs this modal switches between. */
export type AiQuotaModalTab = "auto" | "subscription" | "history"

/** Auto tab's data — the lane the free/auto model draws against. */
export interface AiQuotaModalAutoState {
    /** The lane's two rolling windows. Unset while `isLoading` (or before the first fetch lands). */
    data?: AiQuotaLaneData
    /** `true` → this tab's own fetch is in flight. */
    isLoading: boolean
}

/** Subscription tab's data — the same lane shape, read against the paid plan's own cap. */
export interface AiQuotaModalSubscriptionState {
    /** The lane's two rolling windows, once subscribed. Unset on the free plan or before load. */
    data?: AiQuotaLaneData
    /** `true` → this tab's own fetch is in flight. */
    isLoading: boolean
}

/** History tab's data — the usage chart plus the recent-charges list. */
export interface AiQuotaModalHistoryState {
    /** Day-buckets for the usage chart. */
    chartPoints?: Array<AiQuotaHistoryChartPoint>
    /** Recent charges, most recent first. `undefined` while the first load is still running. */
    items?: Array<AiQuotaHistoryChargeItem>
    /** `true` while the charges list's first load is running. */
    isLoading: boolean
}

/** Props for {@link AiQuotaModal}. */
export interface AiQuotaModalProps {
    /** Whether the modal is currently open. Forwarded to {@link ModalShell}. */
    isOpen: boolean
    /** Open-state change handler — backdrop click, Escape, close button. Forwarded to {@link ModalShell}. */
    onOpenChange: (open: boolean) => void
    /** The viewer's current plan. Drives the header's tier chip (hidden when `null`). */
    tier: AiQuotaTier
    /** Which tab is showing. The CALLER owns this — the block never picks its own tab (Rule 7). */
    activeTab: AiQuotaModalTab
    /** Fired with the tab the viewer picked. */
    onTabChange: (tab: AiQuotaModalTab) => void
    /** Auto tab's lane data. */
    auto: AiQuotaModalAutoState
    /**
     * Subscription tab's Premium lane data — shape matches
     * `AiQuotaSubscriptionPanel`'s own `premiumLane` prop 1:1 (forwarded
     * straight through, unreshaped); `tier` above decides whether that panel
     * even reaches its lane leaf or shows the no-tier CTA instead.
     */
    subscription: AiQuotaModalSubscriptionState
    /** History tab's chart + charges data. */
    history: AiQuotaModalHistoryState
    /** Fired when the subscription tab's upgrade CTA is pressed. The caller owns what happens next (Rule 7). */
    onSubscribe: () => void
    /** Fired when the "view full usage" link is pressed. */
    onViewDetails: () => void
}

/** Tab → label. The block's own vocabulary (§14d.1), same pattern as `ContentModeNav`'s `MODE_LABEL`. */
const TAB_LABEL: Record<AiQuotaModalTab, string> = {
    auto: "Auto",
    subscription: "Subscription",
    history: "History",
}

/** Fixed tab order — a 3-way switch, not caller-supplied labels (§14d.1). */
const TAB_ITEMS: Array<TabItem> = [
    { key: "auto", label: TAB_LABEL.auto },
    { key: "subscription", label: TAB_LABEL.subscription },
    { key: "history", label: TAB_LABEL.history },
]

/** Paid tier → its badge label. */
const TIER_LABEL: Record<Exclude<AiQuotaTier, null>, string> = {
    plus: "Plus",
    pro: "Pro",
    max: "Max",
}

/**
 * The quota-modal scaffold. See the file header for the full contract and the
 * judgement calls made composing it out of the `ai`-group sibling blocks.
 *
 * @param props - {@link AiQuotaModalProps}
 */
const AiQuotaModal = ({
    isOpen,
    onOpenChange,
    tier,
    activeTab,
    onTabChange,
    auto,
    subscription,
    history,
    onSubscribe,
    onViewDetails,
}: AiQuotaModalProps) => {
    // Caller-built header (title + optional tier chip): `ModalShell.title` only carries ONE
    // Typography node, so a second element beside it (the chip) has to compose its own
    // wrapper — which then owns its own `pr-8` for the close button, per ModalShell's
    // caller-built-header contract.
    const titleAndTierChip = [
        () => (
            <Typography
                size="base"
                weight="bold"
                text="AI usage"

            />
        ),
        ...(tier != null ? [() => (
            <Chip tone="accent" text={TIER_LABEL[tier]} />
        )] : []),
    ]

    const header = (
        <div className="pr-8">
            <StackH
                gap={3}
                principle="identity"
                explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                align="center"
                items={titleAndTierChip}
            />
        </div>
    )

    // The one panel slot, filled by whichever sibling block the active tab names. The wrapper
    // shape around it never changes (§11f) — see file header.
    const panel =
        activeTab === "auto" ? (
            <AiQuotaLane
                data={auto.data}
                isLoading={auto.isLoading}


            />
        ) : activeTab === "subscription" ? (
            <AiQuotaSubscriptionPanel
                tier={tier}
                premiumLane={subscription}
                onSubscribe={onSubscribe}


            />
        ) : (
            <AiQuotaHistoryPanel
                chartPoints={history.chartPoints}
                items={history.items}
                isLoading={history.isLoading}


            />
        )

    const tabsAndPanel = [
        () => (
            <div>
                <Tabs
                    items={TAB_ITEMS}
                    selectedKey={activeTab}
                    onSelectionChange={(key) => onTabChange(key as AiQuotaModalTab)}
                    ariaLabel="AI usage"
                />
            </div>
        ),
        () => panel,
    ]

    return (
        <div>
            <ModalShell
                isOpen={isOpen}
                onOpenChange={onOpenChange}
                header={() => header}
                size="lg"
                scroll="inside"
                footer={() => (
                    <LinkSeeMore
                        label="View full usage"
                        onPress={onViewDetails}
                        size="sm"

                    />
                )}
                body={() => <StackV gap={6} items={tabsAndPanel} />}
            />
        </div>
    )
}

