import React from "react"
import type { ReactNode } from "react"
import { Chip } from "@heroui/react"
import { ElementCloseButton } from "@/components/blocks/buttons/ElementCloseButton"

/**
 * Semantic tone of the status chip. Each tone maps to a HeroUI Chip color
 * (the neutral tone maps to the default color).
 */
export type StatusChipTone = "neutral" | "success" | "warning" | "danger" | "accent"

/**
 * Props for the {@link StatusChip} block.
 *
 * Does NOT take `className` (BLOCK-4 — a block hands out no escape hatch; a
 * caller that needs a specific placement uses a frame, not a hole in this
 * component). `icon` stays a rendered `ReactNode` — see the note on
 * {@link StatusChipProps.icon} for why the atom `Chip`'s `icon` slot (a
 * component reference, not an element) isn't a drop-in replacement here.
 */
export interface StatusChipProps {
    /**
     * Semantic tone that drives the chip color. Defaults to "neutral".
     */
    tone?: StatusChipTone
    /**
     * Optional leading icon (typically a Phosphor icon) rendered before the label.
     * A rendered element (`<VerifiedIcon .../>`), not a component reference — the
     * atom `Chip`'s `icon` slot takes an `IconComponent` (a component the atom
     * instantiates itself) instead, so it can't stand in for this prop without
     * changing every call site that renders its own icon element today
     * (`missingVocabulary`: no atom/composite offers an element-shaped leading
     * icon slot on a `Chip`-family component). Root stays HeroUI `Chip` directly
     * for that reason — see the class docstring.
     */
    icon?: ReactNode
    /**
     * Label content rendered inside the chip.
     */
    children: ReactNode
    /**
     * When provided, renders a TRAILING cancel button (X at the end) — click it to
     * remove/cancel the chip. Uses HeroUI `CloseButton` with its OWN default × glyph
     * (per `alert.md`: close-affordances use `CloseButton`, never a hand-rolled
     * `<button><XIcon/>` — and don't override its glyph either; same treatment as
     * `Callout`). When set, the leading {@link StatusChipProps.icon} is DROPPED — a
     * removable/filter chip carries EITHER a leading status icon OR a trailing
     * cancel-X, never both (teacher: "once there's an X, there's no prefix icon").
     */
    onCancel?: () => void
    /**
     * Accessible label for the cancel button (the caller passes a localised string,
     * e.g. `t("common.remove")`). Falls back to HeroUI's default "Close".
     */
    cancelLabel?: string
}

/**
 * Maps a {@link StatusChipTone} to the matching HeroUI Chip color.
 */
const toneToColor: Record<StatusChipTone, "default" | "success" | "warning" | "danger" | "accent"> = {
    neutral: "default",
    success: "success",
    warning: "warning",
    danger: "danger",
    accent: "accent",
}

/**
 * Generic, presentational status chip. A thin pill-shaped wrapper over the
 * HeroUI Chip that maps a semantic tone to a chip color and optionally renders
 * a leading icon before the label. Presentational: the only callback it takes is
 * {@link StatusChipProps.onCancel} for a removable/filter chip (a trailing cancel-X).
 *
 * Root stays raw HeroUI `Chip` rather than the design system's `Chip` atom
 * (`@/components/atoms/chips/Chip`) — the atom's `icon` slot takes an
 * `IconComponent` it instantiates itself, not a rendered element, so it can't
 * carry this block's `icon` prop without breaking every existing call site
 * (see the prop's own docstring). `onCancel` still routes through
 * {@link ElementCloseButton} for the same reason: swapping to the atom's
 * built-in `onRemove` would mean dropping `ElementCloseButton` only on the
 * no-icon branch, splitting the chip's trailing-× styling across two
 * different implementations for no behavioural gain.
 *
 * Does not take `className` (BLOCK-4) — a caller that needs a specific
 * placement composes a frame (`StackH`/`Cluster`/…) around the chip instead.
 * @see Story: .storybook/stories/blocks/chips/StatusChip/StatusChip.stories
 */
export const StatusChip = ({ tone = "neutral", icon, children, onCancel, cancelLabel }: StatusChipProps) => {
    return (
        <Chip
            data-tier="block"
            data-component="StatusChip"
            color={toneToColor[tone]}
            variant="soft"
            size="sm"
            // w-fit: a chip is a hug-content pill by default — an explicit width
            // defeats a parent flex-col's `align-items: stretch` so it never
            // gets stretched full-width (card family §chip). Icon forced to
            // size-4 so every chip icon reads uniformly regardless of caller.
            // Colour is HeroUI's NATIVE soft pairing (`--chip-bg`=`<color>-soft`,
            // `--chip-fg`=`<color>-soft-foreground`) — no hand-rolled tint, so the
            // label + icon inherit an accessibility-tuned foreground (the old
            // `bg-<status>/10 + text-<status>` raw-hue formula failed contrast).
            className="w-fit"
        >
            {/* leading status icon — DROPPED when the chip is removable (has a
                trailing cancel-X): a chip carries EITHER a status icon OR a cancel-X,
                never both. Icon forced to size-4 so it reads uniformly. */}
            {icon && !onCancel ? <span className="shrink-0 [&_svg]:size-4">{icon}</span> : null}
            <Chip.Label>{children}</Chip.Label>
            {onCancel ? (
                // shared close × — bakes transparent-at-rest + tonal hover (same
                // treatment as Callout's dismiss). `tone={tone}` so the X + its hover
                // read the chip's own colour, not a foreign grey.
                <ElementCloseButton
                    label={cancelLabel ?? ""}
                    onPress={onCancel}
                    tone={tone}
                />
            ) : null}
        </Chip>
    )
}

"use client"

import { Chip, ScrollShadow, Tooltip } from "@heroui/react"
import React, { useMemo, useState } from "react"
import { WithClassNames } from "@/modules/types/base/class-name"

/**
 * Props for {@link _TagChips} — presentational; the overflow label already resolved.
 */
export interface TagChipsProps extends WithClassNames<{
    trigger: string
    content: string
}> {
    /** Tag labels to render (e.g. hashtags). */
    tags: Array<string>
    /**
     * Maximum number of tag chips to show before collapsing the rest into a +N chip.
     * @default 3
     */
    maxVisible?: number
    /** Visual variant passed to each `Chip`. */
    variant?: React.ComponentProps<typeof Chip>["variant"]
    /** Already-localized "+N more" label for the overflow chip (interpolated with the count). */
    overflowLabel: string
}

/**
 * Renders tags as `Chip`s; if there are more than `maxVisible` tags, shows only the first
 * `maxVisible` and a +N chip. Hovering the row opens a HeroUI `Dropdown` listing every tag
 * (controlled open + short close delay so the pointer can move into the menu).
 *
 * @param props - {@link TagChipsProps}
 */
export const _TagChips = ({ tags, maxVisible = 3, variant = "soft", overflowLabel, classNames }: TagChipsProps) => {
    const [menuOpen, setMenuOpen] = useState(false)
    const visibleTags = useMemo(() => tags.slice(0, maxVisible), [tags, maxVisible])
    // How many tags were folded away; only when > 0 is there a real "overflow" worth a +N chip (avoids a negative/zero count when empty or not overflowing).
    const overflowCount = Math.max(0, tags.length - maxVisible)
    return (
        <div className="flex items-center gap-2">
            {visibleTags.map((tag, index) => (
                <Chip key={`${String(tag)}-${index}`} variant={variant}>
                    <Chip.Label>{tag}</Chip.Label>
                </Chip>
            ))}
            {overflowCount > 0 && (
                <Tooltip isOpen={menuOpen} onOpenChange={setMenuOpen}>
                    <Tooltip.Trigger className={classNames?.trigger}>
                        <Chip color="default" variant={variant}>
                            <Chip.Label>{overflowLabel}</Chip.Label>
                        </Chip>
                    </Tooltip.Trigger>
                    <Tooltip.Content className={classNames?.content}>
                        <ScrollShadow className="max-h-[200px]" hideScrollBar={true} orientation="horizontal">
                            <div className="flex flex-col gap-2 text-sm">
                                {tags.map((tag) => (
                                    <div key={tag}>{tag}</div>
                                ))}
                            </div>
                        </ScrollShadow>
                    </Tooltip.Content>
                </Tooltip>
            )}
        </div>
    )
}

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Popover } from "@heroui/react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Chip } from "@/components/atoms/chips/Chip"
import { Cluster } from "@/components/frames/Cluster"
import { StackV } from "@/components/frames/Stack"
import { KeyValueList } from "@/components/composites/data/KeyValue"
import { Typography } from "@/components/atoms/text/Typography"

/**
 * DESIGN — a single course/product price: the amount to pay (bold), the struck
 * list price, a `−X%` success chip, and a breakdown popover.
 *
 * ANATOMY IS PER-LEAF: each story below is its OWN leaf and wraps its render in
 * its OWN BlockAnatomy (Diagram + Tree) reflecting the parts THAT leaf composes —
 * there is no separate consolidated "Anatomy" story. The composition shifts with
 * the shape: no-discount shows only the amount; on-sale adds the struck price,
 * chip, popover, and saving line; `showSavingLine={false}` drops that last line.
 */

/** Currency a price is shown in. */
export type PriceCurrency = "VND" | "USD"

/**
 * How loud the price is on its surface — decides the amount's font size. INTERNAL,
 * and deliberately NOT named `role`: that word is a DOM/ARIA attribute, so a prop by
 * that name reads as an accessibility role to both a reader and to eslint-jsx-a11y
 * (which flagged `role="prominent"` as an invalid ARIA role three times).
 * not exposed as a prop (§14d.1): the caller picks a MEMBER (`PriceTagInline` /
 * `PriceTagProminent`), not a size.
 */
export type PriceEmphasis = "inline" | "prominent"

/** Breakdown rows for the breakdown popover (amounts in the SAME currency as the price). */
export interface PriceBreakdown {
    /** Active-phase price BEFORE loyalty (the middle step list -> phase -> charge). */
    phase: number
    /** Localised phase name (e.g. "Early-bird") shown on the phase row. */
    phaseLabel?: string
    /** Loyalty discount percent (0 = no loyalty row). */
    loyaltyPercent: number
    /** Localised loyalty note (e.g. "already owns 2 courses") appended to the loyalty row. */
    loyaltyNote?: string
}

/** Every word the breakdown popover says — resolved by the connected {@link PriceTag}. */
export interface PriceTagLabels {
    /** Popover heading, and its accessible name. */
    breakdownTitle: string
    /** Row label for the pre-discount price. */
    listPrice: string
    /** Row label for the phase discount (already folded with the phase name when there is one). */
    phaseRow: string
    /** Row label for the loyalty discount (already folded with the loyalty note when there is one). */
    loyaltyRow: string
    /** Row label for the total the buyer actually pays. */
    youPay: string
}

/** Props for the {@link PriceTag} block. */
export interface PriceTagProps {
    /** Breakdown-popover copy, already localized. A story passes i18n keys. */
    labels: PriceTagLabels
    /** The price the user actually pays. */
    discounted: number
    /** The pre-discount (list/MSRP) price; struck through when greater than discounted. */
    original?: number | null
    /** Currency to format in. Defaults to "VND". */
    currency?: PriceCurrency
    /**
 * `true` -> the price is in its RESTING state: the amount, the struck-through
 * original price, the `−X%` chip, and the saving line all turn to shimmer,
 * KEEPING the same line boxes so nothing jumps in layout (§8).
 *
 * The flag FLOWS DOWN into the atoms that render each part (`Typography`,
 * `Chip`), instead of building a second shimmer tree (§12c). The popover
 * is TURNED OFF while resting — there is no data to open yet, and a pressable
 * control while loading is a false promise.
 */
    isSkeleton?: boolean
    /**
 * Optional phase-tier + loyalty rows for the breakdown {@link Popover}. Whenever
 * there IS a saving the `−X%` chip is ALWAYS a button that opens the popover (at
 * minimum list price -> "you pay"); `breakdown` just adds the middle steps that
 * explain WHERE the drop came from. Click/tap (not hover) so it works on touch too.
 */
    breakdown?: PriceBreakdown
    /**
 * Show the concrete "save N₫" line under the price (the real VND saved, not just
 * the percent). Defaults to `true`; set `false` where space is tight (dense cards).
 */
    showSavingLine?: boolean
    /** Where the root sits inside its parent. */
    classNames?: Array<AllowedClassName>
}

/**
 * Role -> amount font size.
 */
const AMOUNT_TYPE: Record<PriceEmphasis, "base" | "h4"> = {
    inline: "base",
    prominent: "h4",
}

/** Role -> struck-through original-price line size, placed next to {@link AMOUNT_TYPE} so the two scales don't drift apart. */
const ORIGINAL_TYPE: Record<PriceEmphasis, "xs" | "sm"> = {
    inline: "xs",
    prominent: "sm",
}

/** Format an amount in the given currency. */
export const formatPrice = (amount: number, currency: PriceCurrency): string =>
    currency === "USD"
        ? amount.toLocaleString("en-US", { style: "currency", currency: "USD" })
        : `${amount.toLocaleString("vi-VN")}₫`

/** Whole-percent saving between a "before" and an "after" amount (0 when none). */
const savingPercent = (before: number, after: number): number =>
    before > after ? Math.round((1 - after / before) * 100) : 0

/**
 * The single source of truth for rendering a course/product price: the discounted
 * amount (bold), the list price struck through (only when there IS a saving), and a
 * `−X%` success chip whose percent is the REAL list -> charge gap (phase tier +
 * loyalty). Whenever there is a saving the chip is a clickable button opening a
 * {@link Popover} (at minimum list price -> you pay; `breakdown` adds the phase +
 * loyalty steps). Works in VND or USD.
 *
 * @param props - {@link PriceTagProps}
 */
export const PriceTagBase = ({
    discounted,
    original,
    currency = "VND",
    emphasis,
    isSkeleton = false,
    breakdown,
    showSavingLine = true,
    classNames,
    labels,
}: PriceTagProps & { emphasis: PriceEmphasis }) => {
    const hasSaving = original != null && original > discounted
    const savePercent = hasSaving ? savingPercent(original, discounted) : 0

    // the −X% saving chip — composed from the `Chip` atom (tone success ->
    // soft-success chip, matching src's raw `<Chip variant="soft" color="success">`).
    // The pressable/focusable button role lives on the canonical `Popover.Trigger`
    // wrapper (react-aria: role=button, aria-expanded/controls, tabindex), so there is
    // exactly ONE interactive element. No caret; the whole chip is the affordance.
    const chip =
        savePercent > 0 ? (
            <Chip
                tone="success"
                text={`−${savePercent}%`}
            />
        ) : null

    // phase saving = list -> phase ; loyalty saving = phase -> charge
    const phaseSave = original != null ? savingPercent(original, breakdown?.phase ?? discounted) : 0
    // Popover content — shown for EVERY saving (so the chip is always clickable), at
    // minimum list price -> you pay. The phase-tier & loyalty rows only appear when a
    // full `breakdown` is supplied.
    const breakdownContent = hasSaving ? (
        // Those four rows are all ONE shape: label left <-> value right, repeated =>
        // exactly `KeyValueList` (a repeated list => `items` is DATA). The "you
        // pay" row is the TOTAL row => `emphasis`, not a hand-drawn rule: the frame
        // already knows how to emphasise a total row, and that emphasis looks the same
        // across every price table in the system.
        //
        // WARNING️ The frame does NOT format for you: every money string coming in here
        // has already gone through `formatPrice`.
        // WARNING️ This column is NOT badged: the panel groups nodes BY NAME (`firstEl` keeps
        // only the first element of each name), so two `StackV`s with the same name
        // would MERGE into one node and the tree would read wrong. The node that
        // matters inside the popover is `KeyValueList` — that one is badged; the
        // wrapping column is just `p-3` padding.
        // Two vertical rows inside a design (the eyebrow and the breakdown list) =
        // `grouped`, not `tight`. `tight` (1) is reserved for what sits INSIDE a
        // composite, e.g. the icon+label pair of `InlineIconLabel`.
        <StackV gap={4} principle="cell-pad"
            explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
            padding={4} isSkeleton={isSkeleton} body={() => (
                <StackV gap={4} principle="label-field"
                    explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                    isSkeleton={isSkeleton} items={[
                        ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" text={labels.breakdownTitle} isSkeleton={isSkeleton} />,
                        // No `gap` passed: `KeyValueList` already owns its row rhythm (its own default
                        // is the §10b `grouped` step). Passing one from here overrides the composite's
                        // spacing from OUTSIDE, which §10 forbids — a composite owns its internal
                        // spacing and must not receive it.
                        ({ isSkeleton }: SkeletonProps) => (
                            <KeyValueList
                                isSkeleton={isSkeleton}
                                items={[
                                    {
                                        key: "list",
                                        label: labels.listPrice,
                                        value: formatPrice(original ?? discounted, currency),
                                    },
                                    ...(breakdown && original != null && original > breakdown.phase
                                        ? [{
                                            key: "phase",
                                            label: labels.phaseRow,
                                            // NOTE: `KeyValueListItem.value` is now a plain `string` — this row
                                            // loses the `color="success-soft"` (green) tint it used to carry via
                                            // its own `Typography`. `KeyValueRow` only renders `value` through the
                                            // emphasis/plain split, no per-row tone prop. Preserving the green
                                            // accent needs either accepting the loss (done here) or a future
                                            // `tone`/`accent` field on `KeyValueListItem` — left for whoever owns
                                            // PriceTag/KeyValue next, not decided in this pass.
                                            value: `−${formatPrice(original - breakdown.phase, currency)} (−${phaseSave}%)`,
                                        }]
                                        : []),
                                    ...(breakdown && breakdown.loyaltyPercent > 0 && breakdown.phase > discounted
                                        ? [{
                                            key: "loyalty",
                                            label: labels.loyaltyRow,
                                            // See the "phase" row's note above — same loss of the green tint,
                                            // same reason.
                                            value: `−${formatPrice(breakdown.phase - discounted, currency)} (−${breakdown.loyaltyPercent}%)`,
                                        }]
                                        : []),
                                    {
                                        key: "total",
                                        label: labels.youPay,
                                        value: formatPrice(discounted, currency),
                                        // the TOTAL row: the frame handles the emphasis, replacing a hand-typed `border-t … pt-1`
                                        emphasis: true,
                                    },
                                ]}
                            />
                        ),
                    ]} />
            )} />
    ) : null

    // The price row aligns on BASELINE (big number, struck number, chip share the
    // same text baseline) and wraps on its own when tight => exactly `Cluster`.
    // The three elements are THREE separate items, not merged into one
    // fragment — merging them leaves the frame's `gap` with nowhere to apply.
    const priceRow = (
        <Cluster
            gap={3}
            principle="value-row"
            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
            align="baseline"

            items={[
                // The amount goes through the ATOM `Typography` (§9c), NOT raw
                // HeroUI — thanks to that, `isSkeleton` flows straight into it instead
                // of branching off to build a separate shimmer bar.
                () => (
                    <Typography
                        size={AMOUNT_TYPE[emphasis]}
                        weight="bold"
                        isSkeleton={isSkeleton}
                        classNames={isSkeleton ? ["w-2/3"] : undefined}

                        text={formatPrice(discounted, currency)}
                    />
                ),
                ...(hasSaving
                    ? [() => (
                        <Typography
                            size={ORIGINAL_TYPE[emphasis]}
                            color="muted"
                            isSkeleton={isSkeleton}
                            isStruck
                            classNames={isSkeleton ? ["w-1/3"] : undefined}

                            text={formatPrice(original, currency)}
                        />
                    )]
                    : []),
                // While resting: the chip still holds its place but is NOT wrapped in a
                // Popover — there's no data yet to open, and a pressable control while
                // loading is a false promise.
                ...(isSkeleton
                    ? [() => <Chip isSkeleton />]
                    : savePercent > 0
                        ? [() => (
                            <Popover>
                                <Popover.Trigger
                                    aria-label={labels.breakdownTitle}
                                    className="cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"

                                >
                                    {chip}
                                </Popover.Trigger>
                                <Popover.Content
                                    className="max-w-xs"

                                >
                                    {breakdownContent}
                                </Popover.Content>
                            </Popover>
                        )]
                        : []),
            ]}
        />
    )

    const savingLine = showSavingLine && (isSkeleton || hasSaving) ? (
        <Typography
            size="xs"
            color="muted"
            isSkeleton={isSkeleton}
            classNames={isSkeleton ? ["w-1/2"] : undefined}

            text={hasSaving ? `Save ${formatPrice(original - discounted, currency)}` : undefined}
        />
    ) : null

    return (
        // The outer column = two DIFFERENT lines (the price row · the "saving" line) =>
        // `StackV`, NOT `Cluster`: a cluster is ONE track of N PEER elements (§13b).
        <StackV
            // `grouped` (§10b): the price row and the saving line are two DIFFERENT vertical
            // rows of one design. It was `tight` (1), which §10b reserves for pairs sitting
            // inside a lower-tier component — the saving line read as if it were glued under the number.
            gap={4}
            classNames={classNames}
            isSkeleton={isSkeleton}
            items={[
                () => priceRow,
                () => savingLine,
            ]}
        />
    )
}

"use client"

import React from "react"
import { useTranslations } from "next-intl"
import { Chip } from "@/components/atoms/chips/Chip"

/** Props for {@link CourseTrialChip}. */
export interface CourseTrialChipProps {
    /**
     * The enrollment's paid flag. The chip renders ONLY when this is `false`
     * (a trial / "Trial" placeholder); a real/paid enrollment shows nothing
     * (mark the exception, not the norm).
     */
    isEnrolled: boolean
}

/**
 * Small "Trial" badge for an enrolled-course row — surfaces that a course is
 * still a trial (the learner has not enrolled/paid yet) while progress is still
 * tracked. Soft warning tone; self-hiding for paid courses. Shared by every
 * place that renders the joined-course list (dashboard / profile / settings).
 *
 * @param props - {@link CourseTrialChipProps}
 */
export const CourseTrialChip = ({ isEnrolled }: CourseTrialChipProps) => {
    const t = useTranslations()
    if (isEnrolled) {
        return null
    }
    return (
        <Chip tone="warning" text={t("course.trial")} classNames={["shrink-0"]} />
    )
}

"use client"

import React from "react"
import {
    Chip,
    Modal,
    Typography,
    cn,
} from "@heroui/react"
import { useTranslations } from "next-intl"
import {
    CV_TWO_COLUMN_TEMPLATES,
    type CvDocument,
    type CvTemplate,
} from "@/modules/types/entities/cv"
import { CvHtmlDocument } from "../CvHtmlDocument"

/** The templates the gallery offers, in display order. */
const TEMPLATE_ORDER: ReadonlyArray<CvTemplate> = ["classic", "modern", "sidebar", "minimal"]

/** Props for {@link CvTemplateGalleryModal}. */
export interface CvTemplateGalleryModalProps {
    /** Whether the modal is open. */
    isOpen: boolean
    /** Fired when the modal should open/close. */
    onOpenChange: (isOpen: boolean) => void
    /** The active document — its data feeds every live thumbnail. */
    doc: CvDocument
    /** Fired with the picked template; the caller applies it to `style` + closes. */
    onSelect: (template: CvTemplate) => void
}

/**
 * "Template Gallery" — a modal grid of LIVE template thumbnails (the user's own CvGalleryPage
 * rendered in each layout via {@link CvHtmlDocument}) + name + an ATS badge.
 * Single-column templates read "ATS-safe"; the two-column one carries a
 * warning (ATS parsers + `.docx` export handle it worse — see
 * `CvGalleryPage-TEMPLATES-BRAINSTORM.md`). Picking a card applies the template and closes.
 *
 * @param props - {@link CvTemplateGalleryModalProps}
 */
export const CvTemplateGalleryModal = ({
    isOpen,
    onOpenChange,
    doc,
    onSelect}: CvTemplateGalleryModalProps) => {
    const t = useTranslations()
    const current = doc.style.template ?? "classic"

    const onPick = (template: CvTemplate) => {
        onSelect(template)
        onOpenChange(false)
    }

    return (
        <Modal isOpen={isOpen} onOpenChange={onOpenChange}>
            <Modal.Backdrop>
                <Modal.Container size="lg">
                    <Modal.Dialog className={""}>
                        <Modal.CloseTrigger />
                        <Modal.Header>
                            <Typography type="body" weight="semibold" className="pr-8">
                                {t("cv.builder.template.galleryTitle")}
                            </Typography>
                        </Modal.Header>
                        <Modal.Body>
                            <div className="grid grid-cols-1 gap-4 @app-sm:grid-cols-2">
                                {TEMPLATE_ORDER.map((template) => {
                                    const isTwoColumn = CV_TWO_COLUMN_TEMPLATES.has(template)
                                    const isSelected = current === template
                                    const name = t(`cv.builder.template.names.${template}`)
                                    return (
                                        <div
                                            key={template}
                                            role="button"
                                            tabIndex={0}
                                            aria-pressed={isSelected}
                                            aria-label={t("cv.builder.template.selectAria", { name })}
                                            onClick={() => onPick(template)}
                                            onKeyDown={(event) => {
                                                if (event.key === "Enter" || event.key === " ") {
                                                    event.preventDefault()
                                                    onPick(template)
                                                }
                                            }}
                                            className={cn(
                                                "flex cursor-pointer flex-col overflow-hidden rounded-2xl border bg-surface text-left outline-none transition-colors",
                                                "focus-visible:ring-2 focus-visible:ring-accent",
                                                isSelected ? "border-accent" : "border-default hover:border-accent/60",
                                            )}
                                        >
                                            <div aria-hidden className="h-52 overflow-hidden border-b border-default bg-white">
                                                <div
                                                    className="pointer-events-none origin-top-left"
                                                    style={{ width: 820, transform: "scale(0.34)" }}
                                                >
                                                    <CvHtmlDocument doc={{ ...doc, style: { ...doc.style, template } }} />
                                                </div>
                                            </div>
                                            <div className="flex items-center justify-between gap-2 px-3 py-2">
                                                <div className="flex min-w-0 flex-col">
                                                    <Typography type="body-sm" weight="semibold" className="truncate">
                                                        {name}
                                                    </Typography>
                                                    {isTwoColumn ? (
                                                        <Typography type="body-xs" color="muted">
                                                            {t("cv.builder.template.wordHint")}
                                                        </Typography>
                                                    ) : null}
                                                </div>
                                                <Chip
                                                    size="sm"
                                                    className={cn(
                                                        "shrink-0",
                                                        isTwoColumn ? "bg-warning-soft text-warning-soft-foreground" : "bg-success-soft text-success-soft-foreground",
                                                    )}
                                                >
                                                    <Chip.Label>
                                                        {isTwoColumn ? t("cv.builder.template.atsRisk") : t("cv.builder.template.atsSafe")}
                                                    </Chip.Label>
                                                </Chip>
                                            </div>
                                        </div>
                                    )
                                })}
                            </div>
                        </Modal.Body>
                    </Modal.Dialog>
                </Modal.Container>
            </Modal.Backdrop>
        </Modal>
    )
}

"use client"

import React from "react"
import { Typography, cn } from "@heroui/react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import type { SearchCourseContentItem } from "@/modules/api/graphql/queries/types/search-course-content"
import { EntityResultRow } from "@/components/blocks/learn/EntityResultRow"
import { SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"

/** Props for the {@link ChatToolResult} block. */
export interface ChatToolResultProps extends WithClassNames<undefined> {
    /** The matched sources to render as pickable rows. */
    items: Array<SearchCourseContentItem>
    /** Header label (e.g. "Flashcard", "Related lesson") — translated by the caller. */
    label: React.ReactNode
    /** Header eyebrow icon (phosphor) — signals the result kind at a glance. */
    icon?: React.ReactNode
    /** While the tool runs, mirror the list shape with skeleton rows (no spinner). */
    isLoading?: boolean
    /** Show a kind chip per row — for a MIXED-kind list; off when the header already names one kind. */
    showKindChip?: boolean
    /** Fired when a row is picked — the caller owns navigation. */
    onSelect: (item: SearchCourseContentItem) => void
    /** Optional "see all" affordance below the list (opens the full search view). */
    onViewAll?: () => void
    /** Label for the view-all footer (translated by the caller). */
    viewAllLabel?: React.ReactNode
}

/**
 * In-chat tool-result widget — a labeled, pickable list of RAG hits rendered
 * INLINE inside an assistant {@link import("@/components/blocks/feed/ChatBubble").ChatBubble}
 * (generative-UI message part). Surface-in-surface on the chat popover: a
 * border-only card (no stacked fill — [[card]] §4), a quiet header (eyebrow icon
 * + kind label + count), then shared {@link EntityResultRow}s. Loading mirrors
 * the row shape with skeletons; the caller renders a text fallback (not an empty
 * card) when nothing matched.
 */
export const ChatToolResult = ({
    items,
    label,
    icon,
    isLoading = false,
    showKindChip = false,
    onSelect,
    onViewAll,
    viewAllLabel,
    className,
}: ChatToolResultProps) => {
    return (
        <div className={cn("overflow-hidden rounded-xl border border-default bg-transparent", className)}>
            <div className="flex items-center justify-between gap-2 border-b border-default px-3 py-2">
                <span className="flex min-w-0 items-center gap-2 text-muted">
                    {icon}
                    <Typography type="body-xs" color="muted" truncate>
                        {label}
                    </Typography>
                </span>
                {!isLoading && items.length > 0 ? (
                    <Typography type="body-xs" color="muted" className="shrink-0">
                        {items.length}
                    </Typography>
                ) : null}
            </div>

            {isLoading ? (
                <>
                    {[0, 1].map((row) => (
                        <SurfaceListCardItem key={row}>
                            <div className="flex flex-col gap-2">
                                {showKindChip ? (
                                    <Skeleton.Chip />
                                ) : (
                                    <Skeleton.Typography type="body-xs" width="1/3" />
                                )}
                                <Skeleton.Typography type="body-sm" width="3/4" />
                                <Skeleton.Typography type="body-xs" width="full" />
                            </div>
                        </SurfaceListCardItem>
                    ))}
                </>
            ) : (
                <>
                    {items.map((item, index) => (
                        <EntityResultRow
                            key={`${item.kind}-${item.contentId ?? item.deckId ?? item.taskId ?? index}`}
                            item={item}
                            onSelect={onSelect}
                            showKindChip={showKindChip}
                            showSnippet
                        />
                    ))}
                    {onViewAll ? (
                        <button
                            type="button"
                            onClick={onViewAll}
                            className="group flex w-full cursor-pointer items-center gap-1 px-4 py-2 text-left text-sm font-medium text-accent-soft-foreground"
                        >
                            {viewAllLabel}
                            <ArrowRightIcon
                                aria-hidden
                                focusable="false"
                                className="size-4 transition-transform group-hover:translate-x-0.5"
                            />
                        </button>
                    ) : null}
                </>
            )}
        </div>
    )
}

import React from "react"
import { Chip, Typography, cn } from "@heroui/react"
import { LockSimpleIcon } from "@phosphor-icons/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import type { SearchCourseContentItem } from "@/modules/api/graphql/queries/types/search-course-content"

/**
 * Per-kind presentation of a RAG search hit: when a kind chip is enabled, its
 * label key + Chip color. `code` shares the lesson's presentation (it resolves to
 * a content page). Unknown kinds fall back to `content`.
 */
export const KIND_META = {
    content: { chip: "kindContent", color: "success" },
    code: { chip: "kindContent", color: "success" },
    challenge: { chip: "kindChallenge", color: "warning" },
    flashcard: { chip: "kindFlashcard", color: "accent" },
    milestone: { chip: "kindMilestone", color: "default" },
} as const

type KnownKind = keyof typeof KIND_META

/** Resolve a hit's kind to its presentation, defaulting unknown kinds to content. */
export const metaForKind = (kind: string): (typeof KIND_META)[KnownKind] =>
    KIND_META[kind as KnownKind] ?? KIND_META.content

/** Props for {@link _EntityResultRow} — presentational; labels already resolved. */
export interface EntityResultRowProps extends WithClassNames<undefined> {
    /** The RAG search hit to render (content/challenge/flashcard/milestone). */
    item: SearchCourseContentItem
    /** Fired when the row is clicked — the caller owns navigation. */
    onSelect: (item: SearchCourseContentItem) => void
    /** Show a kind chip above the title (chat tool-result). Default off (quiet related-content list). */
    showKindChip?: boolean
    /** Show a one-line snippet under the title as context. Default off. */
    showSnippet?: boolean
    /** Already-localized kind-chip label (only rendered when `showKindChip` is set). */
    kindLabel: string
    /** Already-localized "Enrol to open" line, shown when `item.isLocked`. */
    enrollToOpenLabel: string
}

/**
 * One pickable RAG result row — the shared row shape behind the content-AI
 * search view, the passive "related content" list, and the in-chat tool-result
 * widget. A nav go-there link: the whole row navigates on click, so hover
 * underlines the TITLE (never a background fill), and the row carries
 * `cursor-pointer` ([[hover-style-matches-clickable-nature]] mode-1 +
 * [[interactive-needs-hover]]). The AFFORDANCE is the title itself — plain
 * `text-foreground` with a hover-underline, NO accent + NO trailing arrow (teacher
 * 2026-07-18: "link foreground only, no arrow" — reversing the same-day
 * accent-title+arrow). Layout: optional kind chip / breadcrumb, then the
 * foreground title, then an optional snippet — all stacked left, no right column.
 *
 * @param props - {@link EntityResultRowProps}
 */
export const _EntityResultRow = ({
    item,
    onSelect,
    showKindChip = false,
    showSnippet = false,
    kindLabel,
    enrollToOpenLabel,
    className,
}: EntityResultRowProps) => {
    const meta = metaForKind(item.kind)
    return (
        <button
            type="button"
            onClick={() => onSelect(item)}
            className={cn(
                "group relative flex w-full cursor-pointer flex-col gap-2 px-4 py-3 text-left after:absolute after:bottom-0 after:left-0 after:h-px after:w-full after:bg-surface-foreground/6 after:content-[''] last:after:hidden",
                className,
            )}
        >
            {showKindChip ? (
                <Chip size="sm" variant="soft" color={meta.color} className="w-fit">
                    {kindLabel}
                </Chip>
            ) : item.breadcrumb ? (
                <Typography type="body-xs" color="muted" truncate>
                    {item.breadcrumb}
                </Typography>
            ) : null}
            {/* affordance = the TITLE itself: FOREGROUND text + hover-underline ONLY — no
                accent, no arrow (teacher 2026-07-18: "link foreground only, no arrow" —
                reversing the same-day accent-title+arrow decision). Nav link → hover underlines the
                title (hover-style §mode-1 + interactive-needs-hover). */}
            <Typography
                type="body-sm"
                weight="medium"
                truncate
                className="text-foreground underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline"
            >
                {item.title}
            </Typography>
            {showSnippet && item.snippet ? (
                <Typography type="body-xs" color="muted" truncate>
                    {item.snippet}
                </Typography>
            ) : null}
            {/* locked = this viewer must enrol to open it (premium lesson / capstone).
                The row still NAVIGATES — landing on the surface's own enrol gate is the
                funnel; this only sets the expectation first. The backend also strips the
                snippet for these, so there is nothing to read here anyway. */}
            {item.isLocked ? (
                <span className="flex items-center gap-1 text-warning-soft-foreground">
                    <LockSimpleIcon aria-hidden focusable="false" className="size-3.5 shrink-0" />
                    <Typography type="body-xs" className="text-warning-soft-foreground">
                        {enrollToOpenLabel}
                    </Typography>
                </span>
            ) : null}
        </button>
    )
}

import { InputSearch } from "@/components/atoms/forms"
import React from "react"
import { CaretRightIcon, CardsIcon, MagnifyingGlassIcon, RowsIcon, SquaresFourIcon } from "@phosphor-icons/react"

import { Tabs, type TabItem } from "@/components/atoms/navigation/Tabs"
import { Pagination } from "@/components/atoms/navigation/Pagination"
import { ProgressGauge } from "@/components/atoms/display/Progress"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import {
    SurfaceCard,
    SurfaceCardList,
    type SurfaceCardListItem,
} from "@/components/composites/cards/SurfaceCard"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { VariantChipDifficulty, type Difficulty } from "@/components/blocks/learn/VariantChip"

/**
 * `FlashcardDeckList` — the course's deck picker: search, switch between a grid
 * of tiles and a scan-friendly line list, page through results, and open any
 * deck. Four leaves: `GridView` (tiles in a responsive `Grid`), `LineView`
 * (rows in one `SurfaceCardList`), `SearchEmpty` (`AsyncContentEmpty`,
 * view-agnostic), and `Loading` (a guessed tile count through each composite's
 * mirror). Toggling `view` or `isSkeleton` on a populated list repaints the same
 * tree.
 */

/** How the deck track is currently laid out. Persisted by the caller, not a leaf-driving prop by itself (see file header). */
export type FlashcardDeckListView = "grid" | "line"

/** One deck row/tile — plain DATA; the block decides which chips and meters it earns. */
export interface FlashcardDeckListDeck {
    /** Stable id — the React key, and what `onSelectDeck` fires with. */
    id: string
    /** Deck title. */
    title: string
    /** Optional blurb. Grid: clamped to two lines. Line: the row's subtitle (falls back to a card count when absent). */
    description?: string
    /** Difficulty tier — the block builds `VariantChipDifficulty` itself. */
    difficulty: Difficulty
    /** Cards due for review right now. Omit or `0` → no due chip (see file header). */
    dueCount?: number
    /** Cards the viewer has already mastered. Paired with `totalCount` for the mastery meter. */
    masteredCount?: number
    /** Total cards in the deck. */
    totalCount: number
}

/** Props for {@link FlashcardDeckList}. */
export interface FlashcardDeckListProps {
    /** The current page's decks, in display order. */
    decks: Array<FlashcardDeckListDeck>
    /** Current search text (controlled). */
    query: string
    /** Fired on every keystroke in the search field. */
    onQueryChange: (query: string) => void
    /**
     * Placeholder AND accessible name for the deck search field — the atom's
     * `InputSearch.ariaLabel` takes no English fallback, so this is required
     * here too; the connected caller resolves it (e.g. the existing
     * `flashcard.searchPlaceholder` i18n key) and passes the translated string.
     */
    searchLabel: string
    /** Which shape the track renders as — a persisted VIEWER SETTING, not a one-off UI toggle. */
    view: FlashcardDeckListView
    /** Fired with the shape the viewer picked. */
    onViewChange: (view: FlashcardDeckListView) => void
    /** 1-based current page. */
    page: number
    /** Total page count — see the file header's "added prop" note. */
    totalPages: number
    /** Fired with the 1-based page the viewer picked. */
    onPageChange: (page: number) => void
    /** Fired with a deck's id when its tile/row is pressed. */
    onSelectDeck: (id: string) => void
    /** Overrides the default grid-tile CTA wording ("Study now"). Localization override, not domain data (mirrors `seeMoreLabel`/`removeLabel`). */
    ctaLabel?: string
    /** `true` → grid tiles and list rows also carry the per-viewer mastery meter. `false` → a plain browse surface with no progress talk. */
    showProgress: boolean
    /** `true` → the track renders its own mirror. `decks` empty while on → guesses a placeholder count in the current `view`'s shape (§12c). */
    isSkeleton?: boolean
}

/** The block's own wording for the grid-tile CTA — overridable via `ctaLabel`. */
const DEFAULT_CTA_LABEL = "Study now"

/** View-toggle tabs — icon only, labels are `sr-only` (the atom takes a `ReactNode` label, so this is within its own contract, not a hack around it). */
const VIEW_ITEMS: Array<TabItem> = [
    { key: "grid", label: <span className="sr-only">Grid view</span>, icon: SquaresFourIcon },
    { key: "line", label: <span className="sr-only">List view</span>, icon: RowsIcon },
]

/** Placeholder rows/tiles for the guessed skeleton count (§12c) — never carry a press handler. */
const skeletonDecks = (count: number): Array<FlashcardDeckListDeck> =>
    Array.from({ length: count }, (_unused, index) => ({
        id: `skeleton-${index}`,
        title: "",
        difficulty: "beginner" as Difficulty,
        totalCount: 0,
    }))

/**
 * The block's decision at a glance:
 * ─────────────────────────────────────────────────────────────────────────────
 * DECIDE → track is empty (search or fetch found nothing) → LEAF 3, everything below skipped
 *        → still no decks AND still loading           → LEAF 4, placeholder count
 *        → view === "grid"                            → LEAF 1
 *        → view === "line"                             → LEAF 2
 * ─────────────────────────────────────────────────────────────────────────────
 *
 * @param props - {@link FlashcardDeckListProps}
 */
const FlashcardDeckList = ({
    decks,
    query,
    onQueryChange,
    searchLabel,
    view,
    onViewChange,
    page,
    totalPages,
    onPageChange,
    onSelectDeck,
    ctaLabel,
    showProgress,
    isSkeleton = false,
}: FlashcardDeckListProps) => {
    // Empty while loading (no real decks yet) → guess a placeholder count in the
    // CURRENT view's shape, keeping the right footprint for when real data lands
    // (§8). Once real `decks` exist, keep the exact count already there.
    const usingPlaceholders = isSkeleton && decks.length === 0
    const source = usingPlaceholders ? skeletonDecks(view === "grid" ? 6 : 4) : decks

    // LEAF 3 — the whole track is replaced by the message; nothing below runs.
    // Reached whether `view` is grid or line, so it forks on data, not on shape.
    const isEmpty = !isSkeleton && decks.length === 0
    const hasQuery = query.trim().length > 0

    /** One grid tile's content — computed only when it will actually render (skeleton tiles never see it). */
    const deckTileBody = (deck: FlashcardDeckListDeck) => {
        const chips: Array<ComponentTypeWithSkeleton> = [
            () => <VariantChipDifficulty difficulty={deck.difficulty} />,
        ]
        if (deck.dueCount) {
            chips.push(() => <Chip tone="warning" text={`${deck.dueCount} due`} />)
        }
        const titleAndDescription = (
            <>
                <Typography size="sm" weight="medium" truncate text={deck.title} />
                {deck.description ? (
                    <Typography size="xs" color="muted" lineClamp={2} text={deck.description} />
                ) : null}
            </>
        )

        const progressRow = (
            <>
                <div className="flex-1">
                    <ProgressGauge
                        value={((deck.masteredCount ?? 0) / deck.totalCount) * 100}
                        size="sm"
                        ariaLabel={`Mastery level for the ${deck.title} deck`}

                    />
                </div>
                <Typography
                    size="xs"
                    color="muted"
                    text={`${deck.masteredCount ?? 0}/${deck.totalCount}`}

                />
            </>
        )

        const ctaRow = (
            <>
                <Typography
                    size="sm"
                    weight="medium"
                    color="accent-soft"
                    text={ctaLabel ?? DEFAULT_CTA_LABEL}

                />
                <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4 shrink-0 text-accent-soft-foreground" />
            </>
        )

        const tileBody = (
            <>
                <StackV gap={1} isSkeleton={isSkeleton} items={[() => titleAndDescription]} />
                <Cluster gap={3} items={chips} />
                {showProgress && deck.totalCount > 0 ? (
                    <StackH gap={2} isSkeleton={isSkeleton} items={[() => progressRow]} />
                ) : null}
                <StackH gap={2} principle="icon-text"
                    explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                    justify="end" isSkeleton={isSkeleton} items={[() => ctaRow]}  />
            </>
        )

        return (
            <StackV gap={3} isSkeleton={isSkeleton} items={[() => tileBody]} />
        )
    }

    const tiles: Array<GridItem> = source.map((deck) => ({
        key: deck.id,
        content: () => (
            <div>
                <SurfaceCard
                    isSkeleton={isSkeleton}
                    // Always set, even during a placeholder tile: `Base`'s skeleton-mirror
                    // branch intercepts BEFORE this ever reaches a real button (see
                    // SurfaceCard.tsx), so it's inert while `isSkeleton` is true — it only
                    // needs to be present so the merged `.Pressable` shape (not the plain
                    // `SurfaceCard` shape) is the one that renders once loading finishes.
                    onPress={() => onSelectDeck(deck.id)}
                    ariaLabel={deck.title}

                    body={() => (isSkeleton ? null : deckTileBody(deck))}
                />
            </div>
        ),
    }))

    const rows: Array<SurfaceCardListItem> = source.map((deck) => {
        const metaChips: Array<ComponentTypeWithSkeleton> = []
        if (!isSkeleton) {
            metaChips.push(() => <VariantChipDifficulty difficulty={deck.difficulty} />)
            if (deck.dueCount) {
                metaChips.push(() => <Chip tone="warning" text={`${deck.dueCount} due`} />)
            }
        }
        return {
            key: deck.id,
            leadingIcon: CardsIcon,
            title: deck.title,
            // The block owns this fallback (§14d.1): a deck with no blurb still says
            // something useful — its card count — instead of a blank second line.
            subtitle: deck.description ?? `${deck.totalCount} cards`,
            meta: metaChips.length > 0 ? () => <Cluster gap={3} items={metaChips} /> : undefined,
            trailing:
                showProgress && !isSkeleton && deck.totalCount > 0
                    ? () => <Typography size="xs" color="muted" text={`${deck.masteredCount ?? 0}/${deck.totalCount}`} />
                    : undefined,
            onPress: usingPlaceholders ? undefined : () => onSelectDeck(deck.id),
        }
    })

    const track = isEmpty ? (
        <AsyncContentEmpty
            icon={hasQuery ? MagnifyingGlassIcon : undefined}
            title={hasQuery ? `No decks match “${query}”` : "This course has no decks yet"}
            description={hasQuery ? "Try a different search term." : undefined}


        />
    ) : view === "grid" ? (
        <div>
            <Grid columns={{ base: 1, sm: 2, md: 3 }} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={tiles}  />
        </div>
    ) : (
        <SurfaceCardList isSkeleton={isSkeleton} items={rows} />
    )

    const searchAndView = (
        <>
            <div className="min-w-0 flex-1">
                <InputSearch
                    value={query}
                    onValueChange={onQueryChange}
                    placeholder={searchLabel}
                    ariaLabel={searchLabel}
                />
            </div>
            <div>
                <Tabs
                    items={VIEW_ITEMS}
                    selectedKey={view}
                    onSelectionChange={(key) => onViewChange(key as FlashcardDeckListView)}
                    ariaLabel="Display style"

                />
            </div>
        </>
    )

    const listBody = (
        <>
            <StackH gap={3} principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                at="sm" isSkeleton={isSkeleton} items={[() => searchAndView]}  />
            {track}
            {!isSkeleton && decks.length > 0 ? (
                <div>
                    <Pagination currentPage={page} totalPages={totalPages} onPageChange={onPageChange} />
                </div>
            ) : null}
        </>
    )

    return (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}
            items={[() => listBody]}
            identity={{ tier: "block", component: "FlashcardDeckList" }}
        />
    )
}

export { FlashcardDeckList }

import React from "react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { Typography } from "@/components/atoms/text/Typography"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { PageHeader } from "@/components/composites/layout/Page"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `FoundationHeader` — the identity cluster at the top of a foundation resource's
 * page: breadcrumb trail, title, description, and a meta row carrying the
 * resource's kind, its recommended flag, its tags, and its author attribution.
 * Two chips (kind and "recommended") both classify the resource. Every optional
 * part — recommended chip, tag row, author line, skeleton — is a data condition
 * on the same trail → title → description → meta shape.
 */

/** Resource kind of a foundation item — mirrors `src`'s `FoundationKind` enum (closed to 3 values). */
export enum FoundationKind {
    /** An external hyperlink (e.g. official docs, article on another site). */
    ExternalLink = "external_link",
    /** An embedded or linked video resource. */
    Video = "video",
    /** A document or written guide, rendered as markdown. */
    Document = "document",
}

/**
 * Kind → chip presentation. EXHAUSTIVE `Record` (not `Partial`, unlike the
 * type `EnumChip` itself accepts): the enum is closed to 3 values, so the
 * compiler must refuse a build that adds a kind and forgets its entry here.
 * The block owns this table (§14d.1: no caller-supplied color/label).
 */
const KIND_MAP: Record<FoundationKind, EnumChipEntry> = {
    [FoundationKind.ExternalLink]: { color: "accent", label: "External link" },
    [FoundationKind.Video]: { color: "accent", label: "Video" },
    [FoundationKind.Document]: { color: "accent", label: "Article" },
}

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface FoundationHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** One topic tag on a foundation resource — plain data, the block builds the chip. */
export interface FoundationHeaderTag {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
}

/** Props for {@link FoundationHeader}. */
export interface FoundationHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. A foundation resource is always reached through its category, so the trail is always required (same call `ModuleHeader` makes for its own always-present trail). */
    breadcrumbItems: Array<FoundationHeaderCrumb>
    /** Resource title. */
    title: string
    /** One-sentence summary of the resource. */
    description?: string
    /** Resource kind — the ONE required classifying fact, drives the `EnumChip` tone + label. */
    kind: FoundationKind
    /** `true` → the resource is editorially highlighted; renders a second, success-toned chip beside the kind chip. */
    isRecommended?: boolean
    /** Topic tags. Empty or omitted → no tag chips render. */
    tags?: Array<FoundationHeaderTag>
    /** Author or source attribution — the block adds "Author: — itself. Omit or empty → no author line. */
    author?: string
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The foundation-resource identity cluster at the top of a resource's own
 * page. See the file header for the full contract and why this is a sibling
 * of `ContentHeader`/`ModuleHeader`/`CourseBrief` rather than an edit of any
 * of them.
 *
 * @param props - {@link FoundationHeaderProps}
 */
const FoundationHeader = ({
    breadcrumbItems,
    title,
    description,
    kind,
    isRecommended = false,
    tags,
    author,
    isSkeleton = false,
}: FoundationHeaderProps) => {
    const hasTags = (tags?.length ?? 0) > 0
    const hasAuthor = author != null && author.trim().length > 0

    const metaCluster = (
        <>
            <StackH
                gap={3}
                principle="chip-row"
                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                align="center"
                at="sm"
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <EnumChip
                            value={isSkeleton ? FoundationKind.Document : kind}
                            map={KIND_MAP}
                            isSkeleton={isSkeleton}

                        />
                    ),
                    ...(isSkeleton
                        ? [() => <Chip isSkeleton />]
                        : isRecommended
                            ? [() => <Chip tone="success" text="Recommended" />]
                            : []),
                    ...(isSkeleton
                        ? [() => <Chip isSkeleton />, () => <Chip isSkeleton />]
                        : hasTags
                            ? (tags ?? []).map((tag) => () => <Chip text={tag.label} />)
                            : []),
                ]}
            />
            {isSkeleton ? (
                <Typography size="xs" color="muted" isSkeleton />
            ) : hasAuthor ? (
                <Typography
                    size="xs"
                    color="muted"
                    text={`Author: ${author}`}

                />
            ) : null}
        </>
    )

    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() => (
                    <div className="w-fit">
                        <Breadcrumbs
                            collapseOnMobile
                            collapseFrom={4}
                            items={breadcrumbItems}
                            isSkeleton={isSkeleton}
                        />
                    </div>
                )}
                title={title}
                description={description}
                meta={() =>
                    <StackV gap={4} isSkeleton={isSkeleton} items={[() => metaCluster]} />
                }
            />
        </div>
    )
}

export { FoundationHeader }

"use client"

import React from "react"
import {
    Chip,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    LockIcon,
} from "@phosphor-icons/react"
import {
    useRouter,
} from "next/navigation"
import {
    useSidebarNavItems,
} from "@/hooks/useSidebarNavItems"
import type {
    LearnNavBadge,
    LearnNavGroup,
} from "@/components/layouts/LearnShellLayout/types"
import { ResumeRail } from "../ResumeRail"
import { CollapsibleSidebar } from "@/components/blocks/navigation/CollapsibleSidebar"
import { SidebarNavGroup } from "@/components/blocks/navigation/SidebarNavGroup"
import { SidebarNavItem } from "@/components/blocks/navigation/SidebarNavItem"
import { SidebarNavAccordionGroup } from "@/components/blocks/navigation/SidebarNavAccordionGroup"

/** localStorage key persisting the learn course-nav collapsed flag. */
const SIDEBAR_STORAGE_KEY = "starci.learn.sidebar.collapsed"

/**
 * Order the labelled nav clusters render in: the mandatory spine (path), then the
 * aids (practice), then the meta surfaces (track). The first group has no divider;
 * every later group gets a full-width {@link SidebarNavGroup} divider on top.
 */
const GROUP_ORDER: ReadonlyArray<LearnNavGroup> = ["path", "practice", "track"]

/**
 * Render a row's trailing status badge: a warning-tinted due-card count, or the
 * viewer's rank as accent text. Kept small so it doesn't crowd the label.
 *
 * @param badge - The {@link LearnNavBadge} to render.
 * @returns The badge node.
 */
const renderBadge = (badge: LearnNavBadge): React.ReactNode => {
    if (badge.tone === "rank") {
        return (
            <Typography type="body-xs" className="text-accent-soft-foreground">
                {`#${badge.value}`}
            </Typography>
        )
    }
    return (
        <Chip size="sm" className="bg-warning-soft text-warning-soft-foreground">
            <Chip.Label>{badge.value}</Chip.Label>
        </Chip>
    )
}

/** Props for {@link LearnSidebar}. */
export type LearnSidebarProps = Record<string, never>
/**
 * Course-learn left navigation rail (desktop).
 *
 * Container: pulls the shared nav entries from {@link useSidebarNavItems} and
 * composes the {@link CollapsibleSidebar} block — which owns the collapse-in-place
 * animation, the toggle, the divider, and persisting the collapsed flag. Rows are
 * split into separator-divided clusters by their `group` (study / practice);
 * each row is a {@link SidebarNavItem} that self-dispatches its tab + navigation
 * through the shared select handler. Hidden below `lg` (mobile uses the drawer in
 * {@link import("../LearnMobileBar").LearnMobileBar}). `"use client"` for the hooks.
 *
 * @param props - {@link LearnSidebarProps}
 */
export const LearnSidebar = () => {
    const t = useTranslations()
    const router = useRouter()
    // shared entries + active tab (also used by the mobile drawer)
    const { items, selectedTab, onSelect } = useSidebarNavItems()
    // role-group captions (sentence case — no uppercase)
    const groupLabels: Record<LearnNavGroup, string> = {
        path: t("nav.groupPath"),
        practice: t("nav.groupPractice"),
        track: t("nav.groupTrack"),
    }
    return (
        <CollapsibleSidebar
            title={t("nav.courseMenu")}
            collapseLabel={t("nav.collapseLeftRail")}
            expandLabel={t("nav.expandLeftRail")}
            storageKey={SIDEBAR_STORAGE_KEY}
            topSlot={<ResumeRail />}
        >
            {GROUP_ORDER.map((group, index) => {
                // rows belonging to this cluster, in their declared order
                const groupItems = items.filter((item) => item.group === group)
                if (groupItems.length === 0) {
                    return null
                }
                return (
                    // first cluster has no divider; later clusters get the full-width separator
                    <SidebarNavGroup key={group} divider={index > 0} label={groupLabels[group]}>
                        {groupItems.map((item) => (
                            item.children ? (
                                <SidebarNavAccordionGroup
                                    key={item.value}
                                    icon={item.icon}
                                    label={item.label}
                                    items={item.children.map((child) => ({
                                        value: child.value,
                                        label: child.label,
                                        isActive: child.isActive,
                                        onPress: () => router.push(child.url),
                                    }))}
                                />
                            ) : (
                                <SidebarNavItem
                                    key={item.value}
                                    icon={<item.icon className="size-5 shrink-0" />}
                                    label={item.label}
                                    isActive={selectedTab === item.tab}
                                    endContent={item.locked ? (
                                        <LockIcon
                                            aria-label={t("enrollGate.locked")}
                                            focusable="false"
                                            className="size-4 text-muted"
                                        />
                                    ) : item.badge ? renderBadge(item.badge) : undefined}
                                    onPress={() => onSelect(item)}
                                />
                            )
                        ))}
                    </SidebarNavGroup>
                )
            })}
        </CollapsibleSidebar>
    )
}

import React from "react"
import { ClockIcon, PuzzlePieceIcon, StackIcon } from "@phosphor-icons/react"
import { CourseContentTier } from "@/modules/types/enums/course-content-tier"
import { Chip } from "@/components/atoms/chips/Chip"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { HighlightChip } from "@/components/composites/chips/HighlightChip"
import { PageHeader } from "@/components/composites/layout/Page"
import { StackH } from "@/components/frames/Stack"

/**
 * `ModuleHeader` — the module-identity cluster at the top of a module's page,
 * answering "what is this module, and how big is it". Sibling of `ContentHeader`
 * and `CourseBrief`: places identity into `PageHeader`, but carries a module's tier
 * plus three `HighlightChip` counts (lessons, minutes, challenges) — the counts are
 * the headline figures, so they keep their chip shape while `tier` classifies the
 * module. Which chips draw stays states of one shape; losing the whole meta row
 * drops a `PageHeader` region and earns its own shape.
 */

/** Tier → chip presentation. The block owns this table (§14d.1: no caller-supplied color/label). */
const TIER_MAP: Record<CourseContentTier, EnumChipEntry> = {
    [CourseContentTier.Foundation]: { color: "success", label: "Foundation" },
    [CourseContentTier.Intermediate]: { color: "warning", label: "Intermediate" },
    [CourseContentTier.Advanced]: { color: "danger", label: "Advanced" },
}

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface ModuleHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** Props for {@link ModuleHeader}. */
export interface ModuleHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. A module is always reached through its course, so the trail is always required (no "no breadcrumb" case, same call `ContentHeader` makes). */
    breadcrumbItems: Array<ModuleHeaderCrumb>
    /** Module title. */
    title: string
    /** One-sentence summary of the module. */
    description?: string
    /** Learning tier — the ONE classifying fact, drives the `EnumChip` tone + label. Omit → no tier chip. */
    tier?: CourseContentTier
    /** How many lessons this module has — the block adds "lessons" itself. Omit or `0` → no chip. */
    lessonCount?: number
    /** Total reading/study minutes across the module — the block adds "minutes of study" itself. Omit or `0` → no chip. */
    minutesTotal?: number
    /** How many challenges hang off this module — the block adds "challenges" itself. Omit or `0` → no chip. */
    challengeCount?: number
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The module identity cluster at the top of a module's own page. See the file
 * header for the full contract and why this is a sibling of `ContentHeader`/
 * `CourseBrief` rather than an edit of either.
 *
 * @param props - {@link ModuleHeaderProps}
 */
const ModuleHeader = ({
    breadcrumbItems,
    title,
    description,
    tier,
    lessonCount,
    minutesTotal,
    challengeCount,
    isSkeleton = false,
}: ModuleHeaderProps) => {
    const hasLessons = (lessonCount ?? 0) > 0
    const hasMinutes = (minutesTotal ?? 0) > 0
    const hasChallenges = (challengeCount ?? 0) > 0
    // The meta row only exists once it has something to show — otherwise `PageHeader`
    // gets `undefined` and drops the whole slot instead of an empty row with nothing in it.
    const hasMeta = isSkeleton || tier != null || hasLessons || hasMinutes || hasChallenges

    const metaRow = hasMeta ? (
        <StackH
            gap={3}
            align="center"
            at="sm"
            principle="chip-row"
            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
            isSkeleton={isSkeleton}

            items={[
                () => (isSkeleton ? (
                    <EnumChip
                        value={CourseContentTier.Foundation}
                        map={TIER_MAP}
                        isSkeleton

                    />
                ) : tier != null ? (
                    <EnumChip value={tier} map={TIER_MAP} />
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={StackIcon} />
                    </span>
                ) : hasLessons ? (
                    <span>
                        <HighlightChip
                            icon={StackIcon}
                            value={lessonCount}
                            label="lessons"
                        />
                    </span>
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={ClockIcon} />
                    </span>
                ) : hasMinutes ? (
                    <span>
                        <HighlightChip
                            icon={ClockIcon}
                            value={minutesTotal}
                            label="minutes"
                        />
                    </span>
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={PuzzlePieceIcon} />
                    </span>
                ) : hasChallenges ? (
                    <span>
                        <HighlightChip
                            icon={PuzzlePieceIcon}
                            value={challengeCount}
                            label="challenges"
                        />
                    </span>
                ) : null),
            ]}
        />
    ) : undefined

    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() => (
                    <div className="w-fit">
                        <Breadcrumbs
                            collapseOnMobile
                            collapseFrom={4}
                            items={breadcrumbItems}
                            isSkeleton={isSkeleton}
                        />
                    </div>
                )}
                title={title}
                description={description}
                meta={() => metaRow}
            />
        </div>
    )
}

